import NumberHelper from "../../../../../../../../helper/NumberHelper";
import {RewardPointHelper} from "../../../../../../helper/RewardPointHelper";

export default {
    getDiscountAmount: {
        reward_points: {
            sortOrder: 10,
            disabled: false,
            after: function(result, creditmemo) {
                if (!RewardPointHelper.isEnabledRewardPoint()) {
                    return result;
                }
                let rewardpointAmount = creditmemo.extension_attributes.rewardpoints_discount || 0;
                return NumberHelper.addNumber(result, rewardpointAmount);
            }
        }
    }
}



