import AmastyRewardCustomerService from "../../../service/customer/AmastyRewardCustomerService";
import CreditmemoConstant from "../../../../../view/constant/order/CreditmemoConstant";
import CreateCreditmemoConstant from "../../../view/constant/order/creditmemo/CreateCreditmemoConstant";
import AmastyRewardsHelper from "../../../helper/AmastyRewardsHelper";
import Action from "../../../../../view/action";
import EpicFactory from "../../../../../framework/factory/EpicFactory";
import NumberHelper from "../../../../../helper/NumberHelper";

/**
 * Receive action CREATE_CREDITMEMO_AFTER and request
 * @param action$
 */
function AmastyRewardPointUpdateLoyaltyEpic(action$) {
    return action$.ofType(CreditmemoConstant.CREATE_CREDITMEMO_AFTER)
        .mergeMap(async action => {
            if (!AmastyRewardsHelper.isEnabledAmastyRewards()) {
                return Action.empty();
            }

            const creditmemo = action.creditmemo;
            const {order} = creditmemo;

            if (order.customer_is_guest || !order.customer_id) {
                return Action.empty();
            }
            let adjustBalance = NumberHelper.minusNumber(
                Number(creditmemo.extension_attributes[CreateCreditmemoConstant.REWARD_POINTS_TO_REFUND] || 0),
                Number(creditmemo.extension_attributes[CreateCreditmemoConstant.EARNED_POINTS] || 0)
            );
            await AmastyRewardCustomerService.rewardCustomerWithPoint(
                order.customer_id,
                adjustBalance
            );

            return Action.empty();
        });
}

AmastyRewardPointUpdateLoyaltyEpic.className = 'AmastyRewardPointUpdateLoyaltyEpic';

export default EpicFactory.get(AmastyRewardPointUpdateLoyaltyEpic);



