import {listen} from "../../../../../../../../event-bus";
import AmastyRewardsHelper from "../../../../../../helper/AmastyRewardsHelper";
import AmastyRewardsAction from "../../../../../../view/action/AmastyRewardsAction";

export default class CheckPromotionAfter {
    /**
     * constructor
     */
    constructor() {
        listen('view_cart_footer_before_to_checkout_check_promotion_after', (eventData) => {
            let {quote} = eventData;
            if (!AmastyRewardsHelper.isEnabledAmastyRewards() || !quote.customer) {
                return;
            }
            let AppStore = require("../../../../../../../../view/store/store").default;
            AppStore.dispatch(AmastyRewardsAction.checkEarningPoint(quote));
        }, 'amasty_rewards');
    }
}



