import AbstractResourceModel from "../../../resource-model/AbstractResourceModel";

export default class AmastyRewardsResourceModel extends AbstractResourceModel {
    static className = 'AmastyRewardsResourceModel';

    /**
     * Constructor
     * @param props
     */
    constructor(props) {
        super(props);
        this.state = {
            resourceName: 'AmastyRewards'
        };
    }

    /**
     * Check earning point
     *
     * @param params
     * @returns {Promise<*>}
     */
    checkEarningPoint(params) {
        return this.getResourceOnline().checkEarningPoint(params);
    }
}



