import CoreService from "../CoreService";
import ServiceFactory from "../../framework/factory/ServiceFactory";
import ConfigHelper from "../../helper/ConfigHelper";
import LogRocketConstant from "../../view/constant/settings/LogRocketConstant";
import LogRocket from "logrocket";
import UserService from "../user/UserService";
import Config from "../../config/Config";

export class LogRocketService extends CoreService {
    static className = 'logRocketService';

    /**
     * Init log rocket
     */
    initLogRocket() {
        if (parseInt(ConfigHelper.getConfig(LogRocketConstant.CONFIG_XML_PATH_LOG_ROCKET_ENABLE), 10)) {
            try {
                let staffName = UserService.getStaffName();
                let staffEmail = UserService.getStaffEmail();
                let staffId = UserService.getStaffId();
                LogRocket.init(ConfigHelper.getConfig(LogRocketConstant.CONFIG_XML_PATH_LOG_ROCKET_APP_ID))
                LogRocket.identify(staffId, {
                    name: staffName + ' - ' + this.getUrlFromBrowser(),
                    email: staffEmail
                });
            } catch (e) {
                return;
            }
        }
    }

    /**
     * get url from browser link
     */
    getUrlFromBrowser() {
        let url = window.location.href;
        url = url.split(Config.basename)[0];
        return url;
    }
}

/** @type LogRocketService */
let logRocketService = ServiceFactory.get(LogRocketService);

export default logRocketService;



