import {combineEpics} from 'redux-observable';
import LogCheckoutPaymentEpic from "./checkout/LogCheckoutPaymentEpic";

/**
 * Combine all log checkout epic
 * @type {Epic<Action, any, any, T> | any}
 */
const LogCheckoutEpic = combineEpics(
    LogCheckoutPaymentEpic
);

export default LogCheckoutEpic;





