import CoreService from "../../../service/CoreService";
import ServiceFactory from "../../../framework/factory/ServiceFactory";
import AmastyRewardsResourceModel from "../resource-model/AmastyRewardsResourceModel";
import CurrencyHelper from "../../../helper/CurrencyHelper";
import AmastyRewardsHelper from "../helper/AmastyRewardsHelper";
import NumberHelper from "../../../helper/NumberHelper";
import AmastyRewardsConstant from "../view/constant/AmastyRewardsConstant";
import AmastyResetRewardProcessor from "./quote/processor/AmastyResetRewardProcessor";

export class AmastyRewardsService extends CoreService {
    static className = 'AmastyRewardsService';
    resourceModel = AmastyRewardsResourceModel;
    usedPoint = 0;
    needResetCreditmemoAdjustmentsPoints = false;

    /**
     * Remove Used Point
     *
     * @returns {AmastyRewardsService}
     */
    removeUsedPoint() {
        return this.setUsedPoint(0);
    }

    /**
     * Get Used Point
     *
     * @return {number}
     */
    getUsedPoint() {
        return this.usePoint;
    }

    /**
     * Set used point
     *
     * @param point
     * @returns {AmastyRewardsService}
     */
    setUsedPoint(point) {
        this.usePoint = point;
        return this;
    }

    /**
     * Check earning point
     *
     * @param quote
     * @returns {Promise<*>}
     */
    checkEarningPoint(quote) {
        let params = {
            quote: this.prepareQuoteParams(quote),
        };
        return this.getResourceModel().checkEarningPoint(params);
    }

    /**
     * prepare params
     *
     * @param quote
     */
    prepareQuoteParams(quote) {
        let quoteData = this.prepareQuoteData(quote);
        quoteData.addresses = this.prepareQuoteAddressesData(quote);
        quoteData.items = this.prepareQuoteItemsData(quote);
        return quoteData;
    }

    /**
     * prepare data
     * @param quote
     * @return {{entity_id}}
     */
    prepareQuoteData(quote) {
        let fields = [
            'store_id', 'is_virtual', 'items_count', 'items_qty', 'grand_total', 'base_grand_total',
            'checkout_method', 'customer_tax_class_id', 'customer_group_id', 'customer_id', 'customer_email',
            'customer_firstname', 'customer_lastname', 'subtotal', 'base_subtotal', 'store_to_base_rate',
            'store_to_base_rate', 'base_to_global_rate', 'base_to_quote_rate', 'base_currency_code',
            'store_currency_code', 'store_currency_code', 'quote_currency_code', 'global_currency_code'
        ];
        let quoteData = {entity_id: quote.id};
        fields.map(field => {
            quoteData[field] = quote[field];
            return field;
        });
        return quoteData;
    }

    /**
     * prepare address
     *
     * @param quote
     * @return {*}
     */
    prepareQuoteAddressesData(quote) {
        if (!quote.addresses || !quote.addresses.length) {
            return [];
        }
        let fields = [
            'address_id', 'quote_id', 'customer_id', 'customer_address_id', 'address_type', 'email', 'firstname',
            'lastname', 'company', 'city', 'region_id', 'postcode', 'country_id', 'telephone', 'same_as_billing',
            'shipping_method', 'shipping_description', 'weight', 'subtotal', 'base_sub_total', 'tax_amount',
            'base_tax_amount', 'shipping_amount', 'base_shipping_amount', 'shipping_tax_amount', 'grand_total',
            'base_grand_total', 'subtotal_incl_tax', 'base_subtotal_total_incl_tax', 'shipping_incl_tax',
            'base_shipping_incl_tax', 'vat_id'
        ];
        return quote.addresses.map(address => {
            let addressData = {};
            fields.map(field => {
                addressData[field] = address[field];
                return field;
            });
            addressData.street = JSON.stringify(address.street);
            addressData.region = address && address.region ? address.region : "";
            return addressData;
        })
    }

    /**
     * prepare items
     *
     * @param quote
     * @return {Array}
     */
    prepareQuoteItemsData(quote) {
        if (!quote.items || !quote.items.length) {
            return [];
        }

        let fields = [
            'item_id', 'quote_id', 'parent_item_id', 'product_id', 'store_id', 'is_virtual', 'sku', 'name',
            'additional_data', 'is_qty_decimal', 'no_discount', 'weight', 'qty', 'price', 'base_price', 'custom_price',
            'tax_percent', 'tax_amount', 'base_tax_amount', 'row_total', 'base_row_total', 'row_weight', 'product_type',
            'price_incl_tax', 'base_price_incl_tax', 'row_total_incl_tax', 'base_row_total_incl_tax', 'custom_options',
            'product_options'
        ];

        return quote.items.map(item => {
            let itemData = {};

            fields.map(field => {
                itemData[field] = item[field];
                return field;
            });

            return itemData;
        })
    }

    /**
     * Get Customer Point Balance
     *
     * @param customer
     * @returns {*|number}
     */
    getCustomerPointBalance(customer) {
        return customer.extension_attributes && customer.extension_attributes.amasty_reward_balance ?
            customer.extension_attributes.amasty_reward_balance : 0;
    }

    /**
     * Get Active Spending Rate Label
     *
     * @return {string}
     */
    getActiveSpendingRateLabel() {
        return `1 ${
            AmastyRewardsHelper.getBalanceLabel()
        } = ${
            CurrencyHelper.convertAndFormat(1 / AmastyRewardsHelper.getSpendingRate(), null)
        }`;
    }

    /**
     * Get Discount Amount By Point
     *
     * @param point
     * @return {number}
     */
    getDiscountAmountByPoint(point) {
        return point / AmastyRewardsHelper.getSpendingRate();
    }

    /**
     * Get Redemption Limit Point Per Order
     *
     * @param quote
     * @returns {null|number}
     */
    getRedemptionLimitPointPerOrder(quote) {
        let redemptionLimitType = AmastyRewardsHelper.getRedemptionLimitType();
        if (redemptionLimitType === AmastyRewardsConstant.REDEMPTION_LIMIT_TYPES_LIMIT_AMOUNT) {
            return AmastyRewardsHelper.getRedemptionLimitAmount();
        } else if (redemptionLimitType === AmastyRewardsConstant.REDEMPTION_LIMIT_TYPES_LIMIT_PERCENT) {
            let limitPercent = AmastyRewardsHelper.getRedemptionLimitPercent();
            let allowedAmount = NumberHelper.multipleNumber((limitPercent / 100), quote.base_subtotal);
            let limitPoint = NumberHelper.multipleNumber(allowedAmount, AmastyRewardsHelper.getSpendingRate());
            limitPoint = Number(limitPoint.toFixed(2));
            return limitPoint;
        }
        return null;
    }

    /**
     * get max points can used to spend for a quote
     *
     * @param quote
     * @return {number}
     */
    getMaximumOfRedeemableForQuote(quote) {
        const spendingRate = AmastyRewardsHelper.getSpendingRate();
        if (!spendingRate) {
            return 0;
        }
        let availablePointBalance = this.getCustomerPointBalance(quote.customer);

        let pointList = [availablePointBalance];

        let maxRedeemablePoint = this.getRedemptionLimitPointPerOrder(quote);
        if (maxRedeemablePoint !== null) {
            pointList.push(maxRedeemablePoint);
        }

        return Math.min(...pointList);
    }

    /**
     * Check Customer Can Spend Point
     *
     * @param customer
     * @return {boolean}
     */
    customerCanSpendPoint(customer) {
        if (!customer || !customer.extension_attributes) {
            return false;
        }

        const pointBalance = this.getCustomerPointBalance(customer);
        const minimumPointsRequirement = AmastyRewardsHelper.getMinimumPointsRequirement();
        if (!minimumPointsRequirement) {
            return pointBalance > 0;
        }

        return pointBalance >= minimumPointsRequirement;
    }

    /**
     * Convert Point To Money
     *
     * @param points
     * @param allItemsPrice
     * @returns {number}
     */
    convertPointToMoney(points, allItemsPrice) {
        let rate = AmastyRewardsHelper.getSpendingRate();
        let roundRule = AmastyRewardsHelper.getRoundRule();
        let basePointsDiscount = points / rate;
        if (allItemsPrice < basePointsDiscount) {
            if (roundRule === AmastyRewardsConstant.ROUND_RULE_DOWN) {
                basePointsDiscount = Math.floor(allItemsPrice);
            } else {
                basePointsDiscount = allItemsPrice;
            }
        }
        return Number(basePointsDiscount);
    }

    /**
     * Filter Data Hold Order
     *
     * @param order
     * @returns {*}
     */
    filterDataHoldOrder(order) {
        AmastyResetRewardProcessor.execute(order);
        if (order.extension_attributes) {
            delete order.extension_attributes.am_spent_reward_points;
            delete order.extension_attributes.am_earn_reward_points;
        }
        delete order.base_discount_amount;
        delete order.discount_amount;
        order.addresses.map(address => {
            if (address.extension_attributes) {
                delete address.extension_attributes.am_spent_reward_points;
                delete address.extension_attributes.am_earn_reward_points;
            }
            delete address.base_discount_amount;
            delete address.discount_amount;
            return address;
        });

        order.items.map(item => {
            if (item.extension_attributes) {
                delete item.extension_attributes.am_spent_reward_points;
                delete item.extension_attributes.am_earn_reward_points;
            }
            delete item.discount_amount;
            delete item.base_discount_amount;
            delete item.discount_percent;
            return item;
        });

        return order;
    }

    /**
     * Calculate Creditmemo Adjustments Point
     *
     * @param creditmemo
     * @param order
     * @param pointsKey
     * @returns {number}
     */
    calculateCreditmemoAdjustmentsPoint(creditmemo, order, pointsKey) {
        let points = 0;

        creditmemo.items.forEach(item => {
            let orderItem = item.order_item;
            if (item.qty
                && orderItem
                && orderItem.extension_attributes
                && orderItem.extension_attributes[pointsKey]
            ) {
                let pointsToRefund = Number(orderItem.extension_attributes[pointsKey]);
                let refundPoints = NumberHelper.multipleNumber(
                    (item.qty / orderItem.qty_ordered),
                    pointsToRefund
                );
                points = NumberHelper.addNumber(points, refundPoints);
            }
        });
        return Number(points.toFixed(2));
    }

    /**
     * Get Need Reset Creditmemo Adjustments Points
     *
     * @returns {boolean}
     */
    getNeedResetCreditmemoAdjustmentsPoints() {
        return this.needResetCreditmemoAdjustmentsPoints;
    }

    /**
     * Set Need Reset Creditmemo Adjustments Points
     *
     * @param {boolean} needResetCreditmemoAdjustmentsPoints
     */
    setNeedResetCreditmemoAdjustmentsPoints(needResetCreditmemoAdjustmentsPoints = false) {
        this.needResetCreditmemoAdjustmentsPoints = needResetCreditmemoAdjustmentsPoints;
    }
}

/**
 * @type {AmastyRewardsService}
 */
let amastyRewardsService = ServiceFactory.get(AmastyRewardsService);

export default amastyRewardsService;



