import AmastyRewardsHelper from "../../../helper/AmastyRewardsHelper";

/**
 * Plugin for customer service
 */
export default {
    needUpdateData: {
        amasty_rewards: {
            sortOrder: 100,
            disabled: false,
            after: function(result) {
                return result || AmastyRewardsHelper.isEnabledAmastyRewards();
            }
        }
    },
};



