import React from 'react';
import CoreComponent from "../../../../../../../framework/component/CoreComponent";
import ComponentFactory from "../../../../../../../framework/factory/ComponentFactory";
import ContainerFactory from "../../../../../../../framework/factory/ContainerFactory";
import CoreContainer from "../../../../../../../framework/container/CoreContainer";
import AmastyRewardsService from "../../../../../service/AmastyRewardsService";
import AmastyRewardsHelper from "../../../../../helper/AmastyRewardsHelper";
import {toast} from "react-toastify";
import AmastyRewardsAction from "../../../../action/AmastyRewardsAction";
import NumberHelper from "../../../../../../../helper/NumberHelper";

export class AmastyPointDiscountComponent extends CoreComponent {
    static className = 'AmastyPointDiscountComponent';

    /**
     * Click Point Discount Button
     *
     * @returns {number|*}
     */
    clickPointDiscountButton() {
        const { actions, quote } =  this.props;
        const minimumPointsRequirement = AmastyRewardsHelper.getMinimumPointsRequirement();
        if ( AmastyRewardsService.getCustomerPointBalance(quote.customer) < minimumPointsRequirement ) {
            return toast.error(
                this.props.t(
                    'Customer must have at least {{minimumPointsRequirement}} to spend point for this order',
                    { minimumPointsRequirement }
                ),
                {className: 'wrapper-messages messages-warning'}
            );
        }

        return actions.checkoutToAmastySpendRewardPoint(quote)
    }

    /**
     * Render spend point total
     *
     * @return {*}
     */
    template() {
        const { total } =  this.props;
        let usedPoints = Number(total.value);
        let classNameAmount = (usedPoints === 0) ? "add-discount" : "amount";
        let pointName = AmastyRewardsHelper.getBalanceLabel();
        let displayValue = (usedPoints === 0) ?
            ""
            : `${NumberHelper.formatDisplayGroupAndDecimalSeparator(usedPoints)} ${pointName}`;
        return (
            <li className="totals-discount totals-action" onClick={() => this.clickPointDiscountButton()}>
                <span className="mark">{total.title}</span>
                <span className={classNameAmount}>{displayValue}</span>
            </li>
        )
    }
}

export class AmastyPointDiscountContainer extends CoreContainer {
    static className = 'AmastyPointDiscountContainer';

    static mapDispatch(dispatch) {
        return {
            actions: {
                checkoutToAmastySpendRewardPoint: (quote) => dispatch(
                    AmastyRewardsAction.checkoutToAmastySpendRewardPoint(quote)
                )
            }
        }
    }
}

/**
 *
 * @type {AmastyPointDiscountContainer}
 */
const container = ContainerFactory.get(AmastyPointDiscountContainer);
export default container.getConnect(ComponentFactory.get(AmastyPointDiscountComponent));



