import AmastyRewardsHelper from "../../../helper/AmastyRewardsHelper";
import NumberHelper from "../../../../../helper/NumberHelper";

export default {
    grand_total_after: [
        /**
         * get template spent point from data order
         *
         * @param component
         * @param orderData
         * @returns {*}
         */
        function getTemplateAmastyRewardSpentPoint(component, orderData) {
            if (AmastyRewardsHelper.isEnabledAmastyRewards()
                && orderData.extension_attributes
                && orderData.extension_attributes.am_spent_reward_points
            ) {
                const pointLabel = AmastyRewardsHelper.getBalanceLabel();
                const {t} = component.props;
                let valueDisplay = orderData.extension_attributes.am_spent_reward_points;
                return component.getTemplateTotal(
                    t('Spent'),
                    t('{{point}} {{pointLabel}}', {
                        point: NumberHelper.formatDisplayGroupAndDecimalSeparator(valueDisplay),
                        pointLabel: pointLabel
                    }),
                    "AmastyRewardSpentPoint",
                    true
                );
            }
            return null;
        }
    ]
}



