import {combineEpics} from 'redux-observable';
import LogCheckoutProcessSinglePaymentErrorEpic from "./payment/LogCheckoutProcessSinglePaymentErrorEpic";
import LogCheckoutProcessSinglePaymentResultEpic from "./payment/LogCheckoutProcessSinglePaymentResultEpic";

/**
 * Combine all log checkout payment epic
 * @type {Epic<Action, any, any, T> | any}
 */
const LogCheckoutPaymentEpic = combineEpics(
    LogCheckoutProcessSinglePaymentErrorEpic,
    LogCheckoutProcessSinglePaymentResultEpic
);

export default LogCheckoutPaymentEpic;





