import {PaymentAbstract} from "./PaymentAbstract";
import PaymentResourceModel from "../../../resource-model/payment/PaymentResourceModel";
import PaymentConstant from "../../../view/constant/PaymentConstant";
import ObjectManager from "../../../framework/ObjectManager";
import ResourceModelFactory from "../../../framework/factory/ResourceModelFactory";
import CurrencyHelper from "../../../helper/CurrencyHelper";
import RefundPopupService from "./stripe/StripeRefundPopupService";
import Constant from "../../../view/constant/payment/StripeConstant";
import Singleton from "../../../resource-model/Singleton";
import NumberHelper from "../../../helper/NumberHelper";

export class StripePayment extends PaymentAbstract {
    code = PaymentConstant.STRIPE_INTEGRATION;
    omc;
    api_url;
    api_namespace;

    constructor() {
        super();
        this.omc = Singleton.getOnline('Payment');
        this.api_namespace = "/V1/webpos/stripe";
        this.api_url = this.omc.getBaseUrl() + this.api_namespace;
    }

    /**
     * run process stripe payment
     * @returns {Promise.<*>}
     */
    async execute() {
        if (this.getCreditmemo()) {
            return await this.sendRefundRequest();
        }

        return await this.sendSaleRequest();
    }
    
    /**
     * Send Sale Request
     *
     * @return {Promise<any>}
     */
    async sendSaleRequest() {
        let errorTransaction = "Transaction Error!";
        try {
            let paymentResourceModel = ObjectManager.get(ResourceModelFactory.get(PaymentResourceModel));
            // get publishable_key from payment
            let paymentFull = await paymentResourceModel.getPaymentFromCode(this.code);
            if (!paymentFull || !paymentFull.publishable_key) {
                errorTransaction = 'Connection failed. Please contact admin to check the configuration of API.';
                return {errorMessage: errorTransaction};
            }
            let public_key = paymentFull.publishable_key;
            // process get token key
            let tokenResponse = await paymentResourceModel.getTokenStripePayment(this.payment, public_key);
            // finish payment and response transaction_id
            if (tokenResponse && tokenResponse.id) {
                let transactionResponse = await paymentResourceModel.stripeFinishPayment(
                    tokenResponse.id,
                    this.payment.base_amount_paid
                );
                return {reference_number: transactionResponse};
            } else {
                return {errorMessage: errorTransaction};
            }
        } catch (error) {
            // error response from get token key
            if (error.error) {
                errorTransaction = error.error.message;
                return {errorMessage: errorTransaction};
            }
            // error response from finish payment
            if (error.message) {
                errorTransaction = error.message;
                return {errorMessage: errorTransaction};
            }
            return {errorMessage: errorTransaction};
        }
    }

    /**
     * Do Post
     *
     * @param url
     * @param body
     * @returns {Promise<any>}
     */
    async doPost(url, body) {
        return await this.omc.post(this.api_url + url, body);
    }
    /**
     * Send Refund Request
     *
     * @return {Promise<any>}
     */
    async sendRefundRequest() {
        let {amount_paid} = this.payment;
        let amount = CurrencyHelper.round(amount_paid, 2);
        amount = NumberHelper.multipleNumber(amount, 100);

        return new Promise((resolve) => {
            const popup = RefundPopupService.showPopup(this, async () => {
                try {
                    let response = await this.doPost('/refund_payment_charge', {
                        request: {
                            paymentChargeId: this.payment.orderPayment.reference_number,
                            amount,
                        }
                    });

                    // process response
                    if (!response.error && !response.message) {
                        this.closePopup();
                        return resolve({
                            reference_number: response.id,
                            error : false,
                        });

                    }

                    return this.showError(popup, response);
                } catch (error) {
                    return this.showError(popup, error);
                }
            }, async () => {
                return resolve({
                    error: true,
                    errorMessage: Constant.MESSAGE_TRANSACTION_STATUS_CANCELLED,
                });
            });
        })
    }

    /**
     * Close Popup
     * 
     */
    closePopup(popup) {
        if (popup) {
            popup.closePopup();
            return this.clear();
        }

        if (RefundPopupService.isOpen()) {
            RefundPopupService.closePopup();
        }

        return this.clear();
    }
}


