import CreateCreditmemoConstant from "../../../../view/constant/order/creditmemo/CreateCreditmemoConstant";
import AmastyRewardsHelper from "../../../../helper/AmastyRewardsHelper";

export default {
    initData: {
        amasty_rewards: {
            sortOrder: 10,
            disabled: false,
            after: function(result, creditmemo, data) {
                if (!AmastyRewardsHelper.isEnabledAmastyRewards()) {
                    return result;
                }
                if (typeof creditmemo.extension_attributes === 'undefined') {
                    creditmemo.extension_attributes = {};
                }
                if (typeof data.extension_attributes !== 'undefined') {
                    if (
                        typeof data.extension_attributes[CreateCreditmemoConstant.EARNED_POINTS] !== 'undefined'
                    ) {
                        creditmemo.extension_attributes[CreateCreditmemoConstant.EARNED_POINTS] =
                            data.extension_attributes[CreateCreditmemoConstant.EARNED_POINTS];
                    }
                    if (typeof data.extension_attributes[CreateCreditmemoConstant.REWARD_POINTS_TO_REFUND] !== 'undefined') {
                        creditmemo.extension_attributes[CreateCreditmemoConstant.REWARD_POINTS_TO_REFUND] =
                            data.extension_attributes[CreateCreditmemoConstant.REWARD_POINTS_TO_REFUND];
                    }
                }
            }
        }
    },
}



