import ModuleConfigAbstract from "../../ModuleConfigAbstract";
import QuoteAddressServicePlugin from "../plugin/service/checkout/quote/QuoteAddressServicePlugin";
import ChangeCustomerServicePlugin from "../plugin/service/checkout/quote/ChangeCustomerServicePlugin";
import CheckoutServicePlugin from "../plugin/service/checkout/CheckoutServicePlugin";

class Config extends ModuleConfigAbstract{
    module = ['add-vat-number'];
    menu = {};
    observer = (() => {})();
    rewrite = {};
    layout = {};
    mixin = {};
    plugin = {
        service: {
            QuoteAddressService: QuoteAddressServicePlugin,
            ChangeCustomerService: ChangeCustomerServicePlugin,
            CheckoutService: CheckoutServicePlugin,
        }
    };
}

export default (new Config());



