import CoreService from "../../../../service/CoreService";
import ServiceFactory from "../../../../framework/factory/ServiceFactory";
import AmastyRewardsHelper from "../../helper/AmastyRewardsHelper";
import ProductTypeConstant from "../../../../view/constant/ProductTypeConstant";
import BundlePriceService from "../../../../service/catalog/product/price/BundlePriceService";
import QuoteItemService from "../../../../service/checkout/quote/ItemService";
import AmastyRewardsConstant from "../../view/constant/AmastyRewardsConstant";

export class AmastySpendingCheckerService extends CoreService {
    static className = 'AmastySpendingCheckerService';

    /**
     * Is Possible Spend On Item
     *
     * @param quote
     * @param item
     * @returns {boolean}
     */
    isPossibleSpendOnItem(quote, item) {
        if (item.product_type === ProductTypeConstant.BUNDLE
            && item.product.price_type === BundlePriceService.PRICE_TYPE_DYNAMIC
        ) {
            return false;
        }
        if (item.parent_item_id
            && QuoteItemService.getParentItem(quote, item).product_type === ProductTypeConstant.CONFIGURABLE
        ) {
            return false;
        }
        if (AmastyRewardsHelper.isSpecificProductsEnabled()
            && (
                AmastyRewardsHelper.getSpecificProductsSku().length
                || AmastyRewardsHelper.getSpecificProductsCategories().length
            )
        ) {
            let skuIds = AmastyRewardsHelper.getSpecificProductsSku();
            let categoryIds = AmastyRewardsHelper.getSpecificProductsCategories();
            let action = AmastyRewardsHelper.getSpecificProductsAction();
            return this.isSuitableItem(quote, item, action, skuIds, categoryIds);
        }
        return true;
    }

    /**
     * Is Suitable Item
     *
     * @param quote
     * @param item
     * @param action
     * @param skuIds
     * @param categoryIds
     * @returns {boolean}
     */
    isSuitableItem(quote, item, action, skuIds, categoryIds) {
        let itemCategoryIds = item.product.category_ids;
        if (skuIds
            && skuIds.length
            && this.getApplicableSkus(quote, item).some(sku => skuIds.includes(sku))
        ) {
            return action === AmastyRewardsConstant.SPECIFIC_PRODUCTS_ACTION_INCLUDE;
        }

        if (categoryIds
            && categoryIds.length
            && categoryIds.some(categoryId => itemCategoryIds.includes(`'${categoryId}'`))
        ) {
            return action === AmastyRewardsConstant.SPECIFIC_PRODUCTS_ACTION_INCLUDE;
        }

        return action === AmastyRewardsConstant.SPECIFIC_PRODUCTS_ACTION_EXCLUDE;
    }

    /**
     * Get Applicable Skus
     *
     * @param quote
     * @param item
     * @returns {*[]}
     */
    getApplicableSkus(quote, item) {
        let skus = [item.product.sku];
        if (item.product_type === ProductTypeConstant.CONFIGURABLE
            && item.product_options
            && item.product_options.simple_sku
        ) {
            skus.push(item.product_options.simple_sku)
        }

        if (item.parent_item_id) {
            skus.push(QuoteItemService.getParentItem(quote, item).product.sku);
        }
        return skus;
    }
}

/**
 * @type {AmastySpendingCheckerService}
 */
let amastySpendingCheckerService = ServiceFactory.get(AmastySpendingCheckerService);

export default amastySpendingCheckerService;



