import {listen} from "../../../../../../../event-bus";
import AmastyRewardsHelper from "../../../../../helper/AmastyRewardsHelper";
import NumberHelper from "../../../../../../../helper/NumberHelper";

export default class RefundOperationServiceObserver {
    /**
     * constructor
     * @param props
     */
    constructor(props) {
        listen('service_creditmemo_refund_operation_refund_after', (eventData) => {
            let {creditmemo, order} = eventData;
            /** reward point */
            if (AmastyRewardsHelper.isEnabledAmastyRewards()) {
                if (!order.extension_attributes) {
                    order.extension_attributes = {};
                }
                order.extension_attributes.am_refund_reward_points = NumberHelper.addNumber(
                    Number(order.extension_attributes.am_refund_reward_points || 0),
                    Number(creditmemo.extension_attributes.reward_points_to_refund || 0)
                );
                order.extension_attributes.am_deduct_reward_points = NumberHelper.minusNumber(
                    Number(order.extension_attributes.am_deduct_reward_points || 0),
                    Number(creditmemo.extension_attributes.earned_points || 0)
                );
            }
        }, 'amasty_rewards');
    }
}



