import {AbstractProcessor} from "../../../../../service/checkout/quote/processor/AbstractProcessor";
import ServiceFactory from "../../../../../framework/factory/ServiceFactory";
import AmastyRewardsHelper from "../../../helper/AmastyRewardsHelper";
import AmastyRewardsConstant from "../../../view/constant/AmastyRewardsConstant";
import NumberHelper from "../../../../../helper/NumberHelper";
import WeeeHelper from "../../../../../helper/WeeeHelper";
import ProductTypeConstant from "../../../../../view/constant/ProductTypeConstant";
import AmastyRewardsService from "../../AmastyRewardsService";

export class AmastyEarningPointProcessor extends AbstractProcessor {
    static className = 'AmastyEarningPointProcessor';

    /**
     * Collect earning point
     *
     * @param quote
     */
    execute(quote) {
        super.execute(quote);
        if (!AmastyRewardsHelper.isEnabledAmastyRewards()
            || !quote.customer
            || (
                quote.extension_attributes
                && quote.extension_attributes.am_spent_reward_points
                && AmastyRewardsHelper.isDisabledEarningByRewards()
            )
            || !quote.amasty_rewards_valid_earning_rules
            || !quote.amasty_rewards_valid_earning_rules.length
        ) {
            return;
        }
        quote.amasty_rewards_valid_earning_rules.forEach(rule => {
            if (rule.action === AmastyRewardsConstant.ORDER_COMPLETED_ACTION) {
                this.calculateByOrderRule(quote, rule);
            } else if (rule.action === AmastyRewardsConstant.MONEY_SPENT_ACTION) {
                this.calculateBySpentRule(quote, rule);
            }
        });
    }

    /**
     * Calculate By Spent Rule
     *
     * @param quote
     * @param rule
     * @param item
     */
    calculateBySpentRule(quote, rule, item) {
        let items = quote.items.filter(item => {
            if (!rule.valid_item_ids || !rule.valid_item_ids.includes(item.item_id)) {
                return false;
            }
            if (Number(rule.skip_discounted_products)) {
                let discountAmount = item.base_discount_amount;
                if (item.extension_attributes && item.extension_attributes.am_spent_reward_points) {
                    discountAmount = NumberHelper.minusNumber(
                        discountAmount,
                        AmastyRewardsService.convertPointToMoney(
                            item.extension_attributes.am_spent_reward_points,
                            item.product.final_price
                        )
                    );
                }
                if (discountAmount > 0) {
                    return false;
                }
            }
            return true;
        });

        let itemsAmount = 0;
        items.forEach(item => {
            itemsAmount = NumberHelper.addNumber(itemsAmount, this.getItemAmount(item));
        });
        if (!itemsAmount) {
            return;
        }
        let spentAmount = Number(rule.spent_amount);
        let rewardAmount = Number(rule.amount);
        let pointsToEarn = NumberHelper.multipleNumber(Math.floor(itemsAmount / spentAmount), rewardAmount);
        let rate = pointsToEarn / itemsAmount;
        let pointsLeft = pointsToEarn;
        items.forEach((item, index) => {
            let itemAmount = this.getItemAmount(item);
            let itemEarnPoints = NumberHelper.multipleNumber(itemAmount, rate);
            pointsLeft = NumberHelper.minusNumber(pointsLeft, itemEarnPoints);
            if (index === (items.length - 1)) {
                itemEarnPoints = NumberHelper.addNumber(itemEarnPoints, pointsLeft);
            }
            item.extension_attributes.am_earn_reward_points = NumberHelper.addNumber(
                item.extension_attributes.am_earn_reward_points,
                itemEarnPoints
            );
        });
        quote.extension_attributes.am_earn_reward_points = NumberHelper.addNumber(
            quote.extension_attributes.am_earn_reward_points,
            pointsToEarn
        );
    }

    /**
     * Calculate By Spent Rule
     *
     * @param quote
     * @param rule
     */
    calculateByOrderRule(quote, rule) {
        let earnPoint = Number(rule.amount);
        quote.extension_attributes.am_earn_reward_points = NumberHelper.addNumber(
            quote.extension_attributes.am_earn_reward_points,
            earnPoint
        );
        quote.items.forEach(item => {
            if (item.product_type === ProductTypeConstant.BUNDLE) {
                return;
            }
            let allItemAmount = this.getAllItemsAmount(quote);
            let itemAmount = this.getItemAmount(item);
            let itemEarnPoint = NumberHelper.multipleNumber((itemAmount / allItemAmount), earnPoint);
            item.extension_attributes.am_earn_reward_points = NumberHelper.addNumber(
                item.extension_attributes.am_earn_reward_points,
                itemEarnPoint
            );
        });
    }

    /**
     * Get All Items Amount
     *
     * @param quote
     * @returns {number}
     */
    getAllItemsAmount(quote) {
        let allItemsAmount = 0;
        quote.items.forEach(item => {
            allItemsAmount = NumberHelper.addNumber(allItemsAmount, this.getItemAmount(item));
        });
        return allItemsAmount;
    }

    /**
     * Get Item Amount
     *
     * @param item
     * @returns {number}
     */
    getItemAmount(item) {
        let calculationMode = AmastyRewardsHelper.getEarningCalculationMode();
        let itemAmount = NumberHelper.minusNumber(item.base_row_total, item.base_discount_amount);
        itemAmount = NumberHelper.addNumber(itemAmount, item.base_discount_tax_compensation_amount);
        if (calculationMode === AmastyRewardsConstant.EARNING_CALCULATION_MODE_AFTER_TAX) {
            itemAmount = NumberHelper.addNumber(itemAmount, item.base_tax_amount);
            if (WeeeHelper.isTaxable()) {
                itemAmount = NumberHelper.addNumber(itemAmount, item.base_weee_tax_applied_row_amnt);
            }
        }
        return itemAmount;
    }
}

/**
 *
 * @type {AmastyEarningPointProcessor}
 */
const amastyEarningPointProcessor = ServiceFactory.get(AmastyEarningPointProcessor);

export default amastyEarningPointProcessor;



