import React, {Fragment} from 'react';
import {CoreComponent} from "../../../../../../../../framework/component/index";
import CoreContainer from "../../../../../../../../framework/container/CoreContainer";
import ComponentFactory from "../../../../../../../../framework/factory/ComponentFactory";
import ContainerFactory from "../../../../../../../../framework/factory/ContainerFactory";
import NumberHelper from "../../../../../../../../helper/NumberHelper";
import CreateCreditmemoConstant from "../../../../../constant/order/creditmemo/CreateCreditmemoConstant";
import NumPad from "../../../../../../../../view/component/lib/react-numpad";
import AmastyRewardsHelper from "../../../../../../helper/AmastyRewardsHelper";

class CreateCreditmemoStepAdjustAmastyPointAdjustmentsComponent extends CoreComponent {
    static className = 'CreateCreditmemoStepAdjustAmastyPointAdjustmentsComponent';

    /**
     *
     * @param props
     */
    constructor(props) {
        super(props);

        this.state = {
            adjustments: this.prepareAdjustments(props),
            errors: {},
        };
    }

    /**
     * Prepare adjustments
     * @param props
     * @return {Array}
     */
    prepareAdjustments(props) {
        const {t} = props;
        let result = [];

        result.push({
            key  : CreateCreditmemoConstant.REWARD_POINTS_TO_REFUND,
            label: t('Refund to Reward Points')
        });
        result.push({
            key  : CreateCreditmemoConstant.EARNED_POINTS,
            label: t('Deduct Reward Points from Customer')
        });
        return result;
    }

    /**
     * Validate adjustment amount after hide numpad
     *
     * @return {boolean}
     */
    validateAdjustmentAmount() {
        let creditmemo = this.props.getCreditmemo();
        if (creditmemo.errors) {
            if (Object.keys(creditmemo.errors).find(key => creditmemo.errors[key])) {
                this.setState({errors: creditmemo.errors});
                return false;
            } else {
                this.setState({errors: {}});
                this.props.setCreditmemo();
            }
        }
    }

    /**
     * Get adjustment amount
     *
     * @return {number}
     */
    getAdjustmentAmount(adjustmentKey) {
        return this.props.adjustments ?
            this.props.adjustments[adjustmentKey] :
            Number(this.props.creditmemo[adjustmentKey] || 0)
    }

    /**
     * Handle Change Amount
     *
     * @param {number} amount
     * @param {string} key
     */
    handleChangeAmount(amount, key) {
        this.props.changeAdjustment(
            {[key]: amount},
            () => this.validateAdjustmentAmount()
        );
    }


    /**
     * template to render
     * @returns {*}
     */
    template() {
        return (
            <Fragment>
                <div className="box">
                    <div className="box-title">{this.props.t('Reward Points Adjustments')}</div>
                    <div className="box-content">
                        {
                            this.state.adjustments.map(adjustment => {
                                let amount = this.getAdjustmentAmount(adjustment.key);
                                return (
                                    <div className="form-group" key={adjustment.key}>
                                        <label>{adjustment.label}</label>
                                        <div className="control">
                                            {
                                                AmastyRewardsHelper.isReadOnlyCreditMemoFields() ?
                                                    <span className="form-control">
                                                        {NumberHelper.formatDisplayGroupAndDecimalSeparator(amount)}
                                                    </span>
                                                    :
                                                    <NumPad.CustomNumber
                                                        onChange={(newAmount) =>
                                                            this.handleChangeAmount(Number(newAmount), adjustment.key)
                                                        }
                                                        isInteger={true}
                                                        position="centerLeft"
                                                        sync={false}
                                                        isShowAction={true}
                                                        arrow="left"
                                                        value={amount}>
                                                        <span className="form-control">
                                                            {NumberHelper.formatDisplayGroupAndDecimalSeparator(amount)}
                                                        </span>
                                                    </NumPad.CustomNumber>
                                            }
                                        </div>
                                        <div className="cas">
                                            {this.state.errors && this.state.errors[adjustment.key]}
                                        </div>
                                    </div>
                                );
                            })
                        }
                    </div>
                </div>
            </Fragment>
        );
    }
}

class CreateCreditmemoStepAdjustAmastyPointAdjustmentsContainer extends CoreContainer {
    static className = 'CreateCreditmemoStepAdjustAmastyPointAdjustmentsContainer';

}

/**
 * @type {CreateCreditmemoStepAdjustAmastyPointAdjustmentsContainer}
 */
export default ContainerFactory.get(CreateCreditmemoStepAdjustAmastyPointAdjustmentsContainer).withRouter(
    ComponentFactory.get(CreateCreditmemoStepAdjustAmastyPointAdjustmentsComponent)
)



