import OrderConstant from '../../../../../view/constant/OrderConstant';
import {Observable} from 'rxjs';
import AmastyRewardsService from "../../../service/AmastyRewardsService";
import EpicFactory from "../../../../../framework/factory/EpicFactory";
import AmastyRewardsHelper from "../../../helper/AmastyRewardsHelper";

/**
 * Receive action type(PLACE_ORDER_AFTER) and request, response list product
 * @param action$
 */
function AmastyRewardPlaceOrderAfterEpic(action$) {
    return action$.ofType(OrderConstant.PLACE_ORDER_AFTER)
        .mergeMap(action => {
            if (!AmastyRewardsHelper.isEnabledAmastyRewards()) {
                return Observable.empty();
            }
            // check and remove used reward point
            const order = action.order;
            if (order.customer_id) {
                AmastyRewardsService.removeUsedPoint();
            }
            return Observable.empty();
        });
}

AmastyRewardPlaceOrderAfterEpic.className = 'AmastyRewardPlaceOrderAfterEpic';

export default EpicFactory.get(AmastyRewardPlaceOrderAfterEpic);



