import AmastyRewardsHelper from "../../../../../helper/AmastyRewardsHelper";
import AmastyRewardsConstant from "../../../../../view/constant/AmastyRewardsConstant";
import CreateCreditmemoConstant from "../../../../../view/constant/order/creditmemo/CreateCreditmemoConstant";

export default {
    collectCreditmemoItemsParamTotal: {
        amasty_rewards: {
            sortOrder: 100,
            disabled: false,
            after: function() {
                if (!AmastyRewardsHelper.isEnabledAmastyRewards()) {
                    return;
                }
                let AmastyRewardsService = require("../../../../../service/AmastyRewardsService").default;
                if (AmastyRewardsService.getNeedResetCreditmemoAdjustmentsPoints()) {
                    let {creditmemo} = this.state;
                    let {order} = this.props;

                    let pointsToRefund = AmastyRewardsService.calculateCreditmemoAdjustmentsPoint(
                        creditmemo,
                        order,
                        AmastyRewardsConstant.POINTS_SPENT
                    );
                    let earnedPoints = AmastyRewardsService.calculateCreditmemoAdjustmentsPoint(
                        creditmemo,
                        order,
                        AmastyRewardsConstant.POINTS_EARN
                    );
                    this.changeAdjustment({
                        [CreateCreditmemoConstant.REWARD_POINTS_TO_REFUND]: pointsToRefund,
                        [CreateCreditmemoConstant.EARNED_POINTS]: earnedPoints
                    });

                }
                AmastyRewardsService.setNeedResetCreditmemoAdjustmentsPoints(false);
            },
        }
    },
};



