import AmastyRewardsHelper from "../../../helper/AmastyRewardsHelper";

/**
 * Plugin to add processor to quote service
 */
export default {
    collectTotals: {
        amasty_rewards: {
            sortOrder: 100,
            disabled: false,
            before: function() {
                if (!AmastyRewardsHelper.isEnabledAmastyRewards()) {
                    return;
                }
                let AmastyResetRewardProcessor = require("../../../service/quote/processor/AmastyResetRewardProcessor").default;
                if (!this.beforeCollectTotalProcessors.find(item => item.class === AmastyResetRewardProcessor)) {
                    this.beforeCollectTotalProcessors.push({
                        class: AmastyResetRewardProcessor,
                        sort_order: 100,
                    });
                }

                let AmastyEarningPointProcessor = require("../../../service/quote/processor/AmastyEarningPointProcessor").default;
                if (!this.afterCollectTotalProcessors.find(item => item.class === AmastyEarningPointProcessor)) {
                    this.afterCollectTotalProcessors.push({
                        class: AmastyEarningPointProcessor,
                        sort_order: 100,
                    });
                }
            },
        }
    },
};



