import {listen} from "../../../../../../../../event-bus";
import AmastyRewardsHelper from "../../../../../../helper/AmastyRewardsHelper";
import AmastyRewardsConstant from "../../../../../../view/constant/AmastyRewardsConstant";

export default class ViewCartTotalPrepareAfter {
    /**
     * constructor
     */
    constructor() {
        listen('view_cart_total_prepare_after', (eventData) => {
            if (!AmastyRewardsHelper.isEnabledAmastyRewards()) {
                return;
            }
            let AmastyRewardsService = require("../../../../../../service/AmastyRewardsService").default;
            let self = eventData.cartTotal;
            const {quote, t} = self.props;

            if (AmastyRewardsService.customerCanSpendPoint(quote.customer)) {
                const pointName = AmastyRewardsHelper.getBalanceLabel();
                const usedPoint = quote.extension_attributes && quote.extension_attributes.am_spent_reward_points ?
                    quote.extension_attributes.am_spent_reward_points
                    : 0;
                let title = t('Spend {{pointName}}', {pointName: pointName});

                self.addToTotals(
                    AmastyRewardsConstant.POINTS_SPENT,
                    title,
                    usedPoint || 0,
                    ""
                );
            }

            if (
                quote.customer
                && (
                    !AmastyRewardsHelper.isDisabledEarningByRewards()
                    || (
                        !(quote.extension_attributes && quote.extension_attributes.am_spent_reward_points)
                        && AmastyRewardsHelper.isDisabledEarningByRewards()
                    )
                )
            ) {
                let earnPoint = quote.extension_attributes && quote.extension_attributes.am_earn_reward_points ?
                    quote.extension_attributes.am_earn_reward_points
                    : 0;
                self.addToTotals(
                    AmastyRewardsConstant.POINTS_EARN,
                    t('Customer can earn'),
                    earnPoint,
                    ""
                );
            }

        }, 'amasty_rewards');
    }
}



