import * as _ from 'lodash';
import {listen} from "../../../../../../../event-bus";
import AmastyRewardsHelper from "../../../../../helper/AmastyRewardsHelper";

export default class ChangeCustomerEpicAfter {
    /**
     * constructor
     */
    constructor() {
        listen('epic_change_customer_after', (eventData) => {
            let {oldCustomer, quote} = eventData;
            let AmastyRewardsService = require("../../../../../service/AmastyRewardsService").default;
            // check and remove used reward point
            if (AmastyRewardsHelper.isEnabledAmastyRewards() && !_.isEqual(oldCustomer,quote.customer)) {
                AmastyRewardsService.removeUsedPoint();
            }
        }, 'amasty_rewards');
    }
}



