import React from 'react';
import CoreComponent from "../../../../../../../framework/component/CoreComponent";
import ComponentFactory from "../../../../../../../framework/factory/ComponentFactory";
import ContainerFactory from "../../../../../../../framework/factory/ContainerFactory";
import CoreContainer from "../../../../../../../framework/container/CoreContainer";
import AmastyRewardsHelper from "../../../../../helper/AmastyRewardsHelper";
import NumberHelper from "../../../../../../../helper/NumberHelper";
import LoadingImage from "../../../../../../../view/style/images/loading.gif";

export class AmastyEarnPointComponent extends CoreComponent {
    static className = 'AmastyEarnPointComponent';
    /**
     * Render earn point total
     *
     * @return {*}
     */
    template() {
        const { value } = this.props.total;
        return (
            <li className={"totals-tax"}>
                <span className="mark">{this.props.total.title}</span>
                {
                    this.props.isCheckingEarnPoint ? (
                        <img className="checking-promotion" src={LoadingImage} alt=""/>
                    ) : (
                        <span className="amount">
                            {
                                this.props.t("{{point}} {{pointName}}", {
                                    point: NumberHelper.formatDisplayGroupAndDecimalSeparator(value),
                                    pointName: AmastyRewardsHelper.getBalanceLabel()
                                })
                            }
                        </span>
                    )
                }
            </li>
        )
    }
}

export class AmastyEarnPointContainer extends CoreContainer {
    static className = 'AmastyEarnPointContainer';

    /**
     * map state to component's props
     *
     * @param state
     * @returns {{showLoading: *}}
     */
    static mapState(state) {
        let {
            isCheckingEarnPoint
        } = state.extension.amastyRewardReducer.earning;
        return {
            isCheckingEarnPoint
        };
    }
}

/**
 *
 * @type {AmastyEarnPointContainer}
 */
const container = ContainerFactory.get(AmastyEarnPointContainer);
export default container.getConnect(ComponentFactory.get(AmastyEarnPointComponent));



