import {listen} from "../../../../../event-bus";
import AmastyRewardsConstant from "../../../view/constant/AmastyRewardsConstant";

export default class CheckoutReducerObserver {
    /**
     * constructor
     */
    constructor() {
        listen('reducer_checkout_index_before', (eventData) => {
            let {state, action} = eventData;
            if (action.type === AmastyRewardsConstant.CHECKOUT_TO_AMASTY_SPEND_REWARD_POINT) {
                let pages = state.pages;
                let AmastySpendRewardPoint = require("../../../view/component/checkout/AmastySpendRewardPoint").default;
                if (pages.indexOf(AmastySpendRewardPoint) === -1) {
                    pages.push(AmastySpendRewardPoint);
                }
                eventData.state = {...state, pages: pages, currentPage: AmastySpendRewardPoint.className};
            }
        }, 'amasty_rewards');
    }
}



