import PerformanceService from "./PerformanceService"
import CoreService from "../CoreService";
import ServiceFactory from "../../framework/factory/ServiceFactory";
import DateTimeHelper from "../../helper/DateTimeHelper";

export class ScheduleService extends CoreService {
    static className = 'ScheduleService';

    /**
     * Check time to sync (if 8h30, 9h, 9h30, it will sync to server)
     *
     * @returns {Promise<void>}
     */
    async checkTimeToSyncInHalfHourInterval() {
        let dateTime = new Date(new Date().getTime() + DateTimeHelper.getTimezoneOffsetTimeStamp());
        let minutes = dateTime.getMinutes();
        if (minutes === 0 || minutes === 30) {
            await PerformanceService.cleanAndCalculatorAverage();
        }
    }
}

/** @type ScheduleService */
let scheduleService = ServiceFactory.get(ScheduleService);

export default scheduleService;



