import {AbstractProcessor} from "../../../../../service/checkout/quote/processor/AbstractProcessor";
import ServiceFactory from "../../../../../framework/factory/ServiceFactory";

export class AmastyResetRewardProcessor extends AbstractProcessor {
    static className = 'AmastyResetRewardProcessor';

    execute(quote) {
        super.execute(quote);
        if (!quote.extension_attributes) {
            quote.extension_attributes = {};
        }
        quote.extension_attributes.am_earn_reward_points = 0;
        quote.extension_attributes.am_spent_reward_points = 0;
        quote.base_discount_amount = 0;
        quote.discount_amount = 0;
        quote.addresses.map(address => {
            if (!address.extension_attributes) {
                address.extension_attributes = {};
            }
            address.extension_attributes.am_earn_reward_points = 0;
            address.extension_attributes.am_spent_reward_points = 0;
            address.base_discount_amount = 0;
            address.discount_amount = 0;
            return address;
        });

        quote.items.map(item => {
            if (!item.product) return item;
            if (typeof item.extension_attributes === 'undefined'){
                item.extension_attributes = {};
            }
            item.extension_attributes.am_earn_reward_points = 0;
            item.extension_attributes.am_spent_reward_points = 0;
            item.discount_amount = 0;
            item.base_discount_amount = 0;
            item.discount_percent = 0;
            return item;
        });
        return this;
    }


}

/**
 *
 * @type {AmastyResetRewardProcessor}
 */
const amastyResetRewardProcessor = ServiceFactory.get(AmastyResetRewardProcessor);

export default amastyResetRewardProcessor;



