import {listen} from "../../../../../../../../event-bus";
import AmastyRewardsHelper from "../../../../../../helper/AmastyRewardsHelper";

export default class ViewCartTotalInitAfter {
    /**
     * constructor
     */
    constructor() {
        listen('constructor_cart_total_init_after', (eventData) => {
            if (AmastyRewardsHelper.isEnabledAmastyRewards()) {
                let AmastySpendRewardPoint = require("../../../../../../view/component/checkout/AmastySpendRewardPoint").default
                eventData.showOnPages.push(AmastySpendRewardPoint.className);
            }
        }, 'amasty_rewards');
    }
}



