import PosService from "../PosService"
import CoreService from "../CoreService";
import PerformanceResourceModel from "../../resource-model/performance/PerformanceResourceModel";
import ServiceFactory from "../../framework/factory/ServiceFactory";
import DateTimeHelper from "../../helper/DateTimeHelper";
import ConfigHelper from "../../helper/ConfigHelper";
import moment from 'moment';

export class PerformanceService extends CoreService {
    static className = 'PerformanceService';

    resourceModel = PerformanceResourceModel;

    /**
     * Tracking performance or not
     *
     * @returns {boolean}
     */
    isEnablePerformanceTrack() {
        if (typeof window.pos.config.config !== 'undefined' && ConfigHelper.getConfig('webpos/performance/enabled')) {
            return !!+ConfigHelper.getConfig('webpos/performance/enabled');
        }
        return true;
    }

    /**
     * Start Measure
     *
     * @param code
     */
    startMeasure(code) {
        if (!this.isEnablePerformanceTrack()) {
            return;
        }
        if (typeof window.countMeasure === "undefined") {
            window.countMeasure = {};
        }
        if (typeof window.countMeasure[code] === "undefined") {
            window.countMeasure[code] = 1;
        } else {
            window.countMeasure[code]++;
        }
        /* Process to mark the process with the same code has different mark*/
        performance.mark('start_' + code + '_' + window.countMeasure[code]);
    }

    /**
     * Stop measure
     *
     * @param code
     */
    async stopMeasure(code) {
        if (!this.isEnablePerformanceTrack()) {
            return;
        }
        let marks = performance.getEntriesByType('mark');
        let findMark = null;
        marks.reverse().map(
            (value) => {
                if (!findMark && value.name.indexOf('start_' + code) > -1) {
                    findMark = value;
                }
                return value;
            }
        )

        /* Measure the mark in the order */
        if (findMark) {
            let measure = performance.measure(
                findMark.name,
                findMark.name
            );

            /* Clear marks after measure */
            performance.clearMarks(findMark.name);
            performance.clearMeasures(findMark.name);

            if (measure) {
                let duration = measure.duration;
                let startTime = parseInt(new Date().getTime() + DateTimeHelper.getTimezoneOffsetTimeStamp() - duration, 10);
                let timeInterval = this.getTimeInterval(startTime);

                let data = {
                    /* make sure it is unique */
                    id: findMark.name + '_' + startTime,
                    start_time: startTime,
                    code: code,
                    duration: duration / 1000,
                    pos_id: PosService.getCurrentPosId(),
                    from: timeInterval.from,
                    to: timeInterval.to
                };

                await this.getResourceModel().saveToDb([data]);
            }
        }
    }

    /**
     * Get the interval which the time is in
     *
     * @param time
     * @returns {{from: string, to: string}}
     */
    getTimeInterval(time) {
        let date = new Date(time);
        let hours = date.getHours();
        let minutes = date.getMinutes();
        let startIntervalHour = hours;
        let startIntervalMinute = 0;
        if (minutes >= 30 && minutes <=59) {
            startIntervalMinute = 30;
        }
        let dateStartInterval = new Date(
            date.getFullYear(),
            date.getMonth(),
            date.getDate(),
            startIntervalHour,
            startIntervalMinute,
            0
        );
        let dateEndInterval = moment(dateStartInterval).add(30, 'm').toDate();
        let from = DateTimeHelper.getFullYear(dateStartInterval) + "-" +
            DateTimeHelper.getMonth(dateStartInterval) + "-" +
            DateTimeHelper.getDate(dateStartInterval) + " " +
            DateTimeHelper.getHours(dateStartInterval) + ":" +
            DateTimeHelper.getMinutes(dateStartInterval) + ":" +
            '00';
        let to = DateTimeHelper.getFullYear(dateEndInterval) + "-" +
            DateTimeHelper.getMonth(dateEndInterval) + "-" +
            DateTimeHelper.getDate(dateEndInterval) + " " +
            DateTimeHelper.getHours(dateEndInterval) + ":" +
            DateTimeHelper.getMinutes(dateEndInterval) + ":" +
            '00';
        return {
            from: from,
            to: to
        };
    }

    /**
     * Clean and calculator average
     *
     * @returns {Promise<*[]>}
     */
    async cleanAndCalculatorAverage() {
        if (!this.isEnablePerformanceTrack()) {
            return;
        }
        let collection = await this.getResourceModel().getAll();

        let result = {}

        collection.map(
            (value) => {
                if (value.pos_id) {
                    if (typeof result[value.pos_id] === 'undefined') {
                        result[value.pos_id] = {};
                    }
                    if (typeof result[value.pos_id][value.from] === 'undefined') {
                        result[value.pos_id][value.from] = {
                            'from': value.from,
                            'to': value.to,
                            'result': {}
                        };
                    }
                    if (typeof result[value.pos_id][value.from]['result'][value.code] === 'undefined') {
                        result[value.pos_id][value.from]['result'][value.code] = {
                            'sum': value.duration,
                            'count': 1
                        };
                    } else {
                        result[value.pos_id][value.from]['result'][value.code]['sum'] += value.duration;
                        result[value.pos_id][value.from]['result'][value.code]['count']++;
                    }
                }
                return value;
            }
        );
        let resultToSync = this.calculateAverageBySumAndCount(result);
        return this.syncPerformanceToServer(resultToSync);
    }

    /**
     * Calculate average by sum and count
     *
     * @param result
     * @param from
     * @param to
     * @returns {[]}
     */
    calculateAverageBySumAndCount(result) {
        if (!this.isEnablePerformanceTrack()) {
            return;
        }
        let averageResult = [];
        for (const [posId, resultOfPos] of Object.entries(result)) {
            for (const [startInterval, value] of Object.entries(resultOfPos)) {
                let from = startInterval;
                let to = value.to;
                let valueResult = value.result;
                for (const [code, valueSum] of Object.entries(valueResult)) {
                    let average = valueSum.sum / valueSum.count;
                    averageResult.push(
                        {
                            action_code: code,
                            average: average,
                            total_count: valueSum.count,
                            pos_id: posId,
                            from: from,
                            to: to
                        }
                    );
                }
            }
        }
        return averageResult;
    }

    /**
     * Call api to save
     *
     * @param result
     * @returns {Promise<void>}
     */
    async syncPerformanceToServer(result) {
        if (!this.isEnablePerformanceTrack()) {
            return;
        }
        if (result.length) {
            let apiResult = await this.getResourceModel().saveLog(
                {
                    'performanceTrack': result
                }
            );
            if (apiResult === true) {
                /* Delete all after sync success */
                await this.getResourceModel().deleteAll();
            }
        }
    }
}

/** @type PerformanceService */
let performanceService = ServiceFactory.get(PerformanceService);

export default performanceService;



