import AmastyRewardsConstant from '../constant/AmastyRewardsConstant';

export default {
    /**
     * Check Earning Point
     *
     * @param quote
     * @return {{type: string, quote: *}}
     */
    checkEarningPoint: (quote) => {
        return {
            type: AmastyRewardsConstant.CHECK_EARNING_POINT,
            quote
        }
    },

    /**
     * Check Earning Point Result
     *
     * @return {{type: string}}
     */
    checkEarningPointResult: () => {
        return {
            type: AmastyRewardsConstant.CHECK_EARNING_POINT_RESULT
        }
    },

    /**
     * Checkout To Amasty Spend Reward Point
     *
     * @param quote
     * @return {{type: string, quote: *}}
     */
    checkoutToAmastySpendRewardPoint: (quote) => {
        return {
            type: AmastyRewardsConstant.CHECKOUT_TO_AMASTY_SPEND_REWARD_POINT,
            quote
        }
    },
}



