import React, {Fragment} from 'react';
import {listen} from "../../../../../../event-bus";
import NumberHelper from "../../../../../../helper/NumberHelper";
import AmastyRewardsHelper from "../../../../helper/AmastyRewardsHelper";
import CreateCreditmemoConstant from "../../../../view/constant/order/creditmemo/CreateCreditmemoConstant";

export default class PrintComponentObserver {
    /**
     * constructor
     */
    constructor() {
        listen('view_print_get_template_plugin_area_before', (eventData) => {
            let {component, creditmemo} = eventData;
            if (AmastyRewardsHelper.isEnabledAmastyRewards()) {
                eventData.listTemplate.push(this.getTemplateAdjustPointDetail(component, creditmemo));
            }
        }, 'amasty_rewards');
    }

    /**
     * Get template adjust point balance
     *
     * @param component
     * @param creditmemo
     * @returns {{template: null, sortOrder: number}}
     */
    getTemplateAdjustPointDetail(component, creditmemo) {
        let template = {
            template: null,
            sortOrder: 10
        };
        const pointLabel = AmastyRewardsHelper.getBalanceLabel();
        let deductedPoints = 0;
        if (creditmemo
            && creditmemo.extension_attributes
            && creditmemo.extension_attributes[CreateCreditmemoConstant.EARNED_POINTS]
        ) {
            deductedPoints = creditmemo.extension_attributes[CreateCreditmemoConstant.EARNED_POINTS];
        }

        let refundedPoints = 0;
        if (creditmemo
            && creditmemo.extension_attributes
            && creditmemo.extension_attributes[CreateCreditmemoConstant.REWARD_POINTS_TO_REFUND]
        ) {
            refundedPoints = creditmemo.extension_attributes[CreateCreditmemoConstant.REWARD_POINTS_TO_REFUND];
        }

        const {t} = component.props;
        if (creditmemo && (deductedPoints || refundedPoints)) {
            template.template = (
                <Fragment key='AmastyAdjustPointDetail'>
                    {
                        deductedPoints ? component.getTemplateTotal(
                            t('Reward Points Subtracted'),
                            t('{{point}} {{pointLabel}}', {
                                point: NumberHelper.formatDisplayGroupAndDecimalSeparator(deductedPoints),
                                pointLabel: pointLabel
                            }),
                            "Deduct Reward Points",
                            true
                        ) : null
                    }
                    {
                        refundedPoints ? component.getTemplateTotal(
                            t('Reward Points Refunded'),
                            t('{{point}} {{pointLabel}}', {
                                point: NumberHelper.formatDisplayGroupAndDecimalSeparator(refundedPoints),
                                pointLabel: pointLabel
                            }),
                            "Reward Points Refunded",
                            true
                        ) : null
                    }
                </Fragment>
            );
        }

        return template;
    }
}



