import ModuleConfigAbstract from "../../ModuleConfigAbstract";
import Customer from "../layout/Customer";
import CartTotalsComponentPlugin from "../plugin/view/component/checkout/cart/CartTotalsComponentPlugin";
import ViewCartTotalPrepareAfter from "../observer/view/component/checkout/cart/cart-total/ViewCartTotalPrepareAfter";
import SingletonObserver from "../observer/resource-model/SingletonObserver";
import CheckPromotionAfter from "../observer/view/component/checkout/cart/cart-footer/CheckPromotionAfter";
import QuoteServicePlugin from "../plugin/service/checkout/QuoteServicePlugin";
import CustomerServicePlugin from "../plugin/service/customer/CustomerServicePlugin";
import ViewCartTotalInitAfter from "../observer/view/component/checkout/cart/cart-total/ViewCartTotalInitAfter";
import ChangeCustomerEpicAfter from "../observer/view/epic/checkout/quote/ChangeCustomerEpicAfter";
import CheckoutReducerObserver from "../observer/view/reducer/CheckoutReducerObserver";
import QuoteServiceObserver from "../observer/service/checkout/QuoteServiceObserver";
import MenuComponentPlugin from "../plugin/view/component/menu/MenuComponentPlugin";
import CartTotalsDiscountComponentPlugin
    from "../plugin/view/component/checkout/cart/totals/CartTotalsDiscountComponentPlugin";
import TotalServiceObserver from "../observer/service/checkout/quote/TotalServiceObserver";
import CheckoutServiceObserver from "../observer/service/checkout/CheckoutServiceObserver";
import HoldOrderProcessBefore from "../observer/service/sales/on-hold-order/HoldOrderProcessBefore";
import TemplateReceiptLayout from "../layout/print/print-component/TemplateReceiptLayout";
import OrderDetailLayout from "../layout/order/OrderDetailLayout";
import CreateCreditmemoStepAdjustmentLayout
    from "../layout/order/order-detail/create-creditmemo/CreateCreditmemoStepAdjustmentLayout";
import OrderCreateCreditmemoObserver
    from "../observer/view/component/order/order-detail/OrderCreateCreditmemoObserver";
import OrderCreateCreditmemoComponentPlugin
    from "../plugin/view/component/order/order-detail/OrderCreateCreditmemoComponentPlugin";
import CreditmemoFactoryServicePlugin from "../plugin/service/sales/order/CreditmemoFactoryServicePlugin";
import RefundOperationServiceObserver from "../observer/service/sales/order/creditmemo/RefundOperationServiceObserver";
import PrintComponentObserver from "../observer/view/component/print/PrintComponentObserver";
import amastyRewardReducer from "../view/reducer/AmastyRewardsReducer";
import CheckoutServicePlugin from "../plugin/service/checkout/CheckoutServicePlugin";

class Config extends ModuleConfigAbstract{
    module = ['amasty-rewards'];
    menu = {};
    observer = (() => {
        // Listen event by pure function
        // Listen event by Object
        new ViewCartTotalInitAfter();
        new ViewCartTotalPrepareAfter();
        new SingletonObserver();
        new CheckPromotionAfter();
        new ChangeCustomerEpicAfter();
        new CheckoutReducerObserver();
        new QuoteServiceObserver();
        new TotalServiceObserver();
        new CheckoutServiceObserver();
        new HoldOrderProcessBefore();
        new OrderCreateCreditmemoObserver();
        new RefundOperationServiceObserver();
        new PrintComponentObserver();

        return null;
    })();
    reducer = {
        amastyRewardReducer
    };
    rewrite = {
    };
    plugin = {
        component: {
            CartTotalsComponent: CartTotalsComponentPlugin,
            MenuComponent: MenuComponentPlugin,
            CartTotalsDiscountComponent: CartTotalsDiscountComponentPlugin,
            OrderCreateCreditmemoComponent: OrderCreateCreditmemoComponentPlugin
        },
        service: {
            QuoteService: QuoteServicePlugin,
            CustomerService: CustomerServicePlugin,
            CreditmemoFactoryService: CreditmemoFactoryServicePlugin,
            CheckoutService: CheckoutServicePlugin
        },
    };
    layout = {
        customer: Customer,
        print: {
            template_receipt_layout: TemplateReceiptLayout,
        },
        order: {
            order_detail: {
                create_creditmemo: {
                    step_adjustment_layout: CreateCreditmemoStepAdjustmentLayout,
                }
            },
            order_detail_layout: OrderDetailLayout,
        }
    };
}

export default (new Config());



