import React from 'react';
import PropTypes from 'prop-types';
import CoreComponent from '../../../../../../framework/component/CoreComponent'
import ComponentFactory from "../../../../../../framework/factory/ComponentFactory";

export class CustomSaleCheckboxComponent extends CoreComponent {
    static className = 'CustomSaleCheckboxComponent';
    input;

    /**
     * constructor
     *
     * @param props
     */
    constructor(props) {
        super(props);
        this.state = {
            defaultValue: props.DefaultValue
        }
    }

    /**
     * Component will receive props
     *
     * @param nextProps
     */
    componentWillReceiveProps(nextProps) {
        if(nextProps.isNew){
            this.setState({
                value: this.props.DefaultValue,
            });
            this.input.checked = this.props.DefaultValue;
            this.props.onSelect(this.props.Code, this.props.DefaultValue);
        }
    }

    /**
     * set input
     *
     * @param input
     */
    setInput(input) {
        this.input = input;
    }

    /**
     * Onchange
     */
    onChange() {
        if (this.props.onSelect) {
            let value = this.input.checked ? 1 : 0;
            this.props.onSelect(this.props.Code, value);
        }
    }

    /**
     * Template
     *
     * @returns {*}
     */
    template() {
        let { Label, OneRow, Disabled } = this.props;
        return (
            <div className={OneRow ? "col-sm-12" : "col-sm-6"}>
                <label className="pull-left"> { Label } </label>
                <div className="checkbox pull-right">
                    <label>
                        <input type="checkbox"
                               defaultChecked={this.state.defaultValue}
                               ref={this.setInput.bind(this)}
                               disabled={Disabled}
                               onChange={this.onChange.bind(this)}/>
                        <span><span>no</span></span>
                    </label>
                </div>
            </div>
        )
    }
}

CustomSaleCheckboxComponent.propTypes = {
    Label: PropTypes.string,
    OneRow: PropTypes.bool,
    onSelect: PropTypes.func,
    Disabled: PropTypes.bool
};

/**
 * CustomSaleCheckboxComponent
 */
export default ComponentFactory.get(CustomSaleCheckboxComponent);



