import React from 'react';
import NumPad from '../../../../../view/component/lib/react-numpad';
import {CoreComponent} from "../../../../../framework/component";
import CoreContainer from "../../../../../framework/container/CoreContainer";
import CheckoutAction from "../../../../../view/action/CheckoutAction";
import ComponentFactory from "../../../../../framework/factory/ComponentFactory";
import ContainerFactory from "../../../../../framework/factory/ContainerFactory";
import AmastyRewardsHelper from "../../../helper/AmastyRewardsHelper";
import CurrencyHelper from "../../../../../helper/CurrencyHelper";
import AmastyRewardsService from "../../../service/AmastyRewardsService";
import QuoteService from "../../../../../service/checkout/QuoteService";
import QuoteAction from "../../../../../view/action/checkout/QuoteAction";
import '../../style/css/AmastyReward.css';
import NumberHelper from "../../../../../helper/NumberHelper";

export class AmastySpendRewardPointComponent extends CoreComponent {
    static className = 'AmastySpendRewardPointComponent';

    /**
     * constructor
     *
     * @param props
     */
    constructor(props) {
        super(props);
        let usePoint = props.quote.extension_attributes && props.quote.extension_attributes.am_spent_reward_points ?
            props.quote.extension_attributes.am_spent_reward_points
            : 0;

        this.state = {
            usePoint: usePoint
        };
    }

    /**
     * Component will receive props
     *
     * @param nextProps
     */
    componentWillReceiveProps(nextProps) {
        let maxPoint = AmastyRewardsService.getMaximumOfRedeemableForQuote(nextProps.quote);
        if (this.state.usePoint >= maxPoint) {
            this.setState({
                usePoint: maxPoint
            });
        }
    }

    /**
     * Handle change use point
     *
     * @param usePoint
     */
    handleChangeUsePoint(usePoint) {
        this.setState({
            usePoint
        });
    }

    /**
     * Click use points
     */
    clickUsePoints() {
        const {actions, quote} = this.props;
        AmastyRewardsService.setUsedPoint(this.state.usePoint);
        QuoteService.collectTotals(quote);
        let newQuote = {...quote};

        actions.setQuote(newQuote);

        actions.checkoutToSelectPayments(newQuote);
    }

    /**
     * template to render
     * @returns {*}
     */
    template() {
        const {usePoint} = this.state;
        const {t, availablePointBalance, actions, quote} = this.props;
        const maximumOfRedeemable = AmastyRewardsService.getMaximumOfRedeemableForQuote(quote);
        const pointDiscount = AmastyRewardsService.getDiscountAmountByPoint(usePoint);
        const pointName = AmastyRewardsHelper.getBalanceLabel();
        const canUsePoint = true;
        return (
            <div className="wrapper-payment active">
                <div className="block-title">
                    <strong className="title">{t('Reward Point')}</strong>
                </div>
                <div className="block-content" data-scrollbar>
                    <div className="payment-logo point-logo">

                    </div>
                    <ul className="payment-total">
                        <li>
                            <span className="label">{t('{{pointName}} Balance', {pointName})}</span>
                            <span className="value">
                                {NumberHelper.formatDisplayGroupAndDecimalSeparator(availablePointBalance)}&nbsp;
                                <small>
                                    {t('{{pointName}}', {pointName: pointName})}
                                </small>
                            </span>
                        </li>
                    </ul>
                    <NumPad.CustomNumber
                        onChange={(newUsePoint) => {
                            newUsePoint = Math.abs(Number(newUsePoint));
                            if (newUsePoint > maximumOfRedeemable) {
                                return this.handleChangeUsePoint(maximumOfRedeemable)
                            }
                            this.handleChangeUsePoint(newUsePoint);
                        }}
                        isInteger={true}
                        position="centerLeft"
                        sync={false}
                        isShowAction={true}
                        arrow="left"
                        value={usePoint}>
                        <div className={"payment-amount use-points"}>
                            <span className="label">
                            {t('Use {{pointName}}', {pointName: pointName})}
                            <span>{t(AmastyRewardsService.getActiveSpendingRateLabel())}</span>
                            </span>
                            <span className="value">
                                {NumberHelper.formatDisplayGroupAndDecimalSeparator(usePoint)}
                            </span>
                        </div>
                    </NumPad.CustomNumber>
                    <div className="payment-point-discount">
                        <span className="label">{t('{{pointName}} Discount', {pointName})}</span>
                        <span className="value">{CurrencyHelper.convertAndFormat(pointDiscount, null)}</span>
                    </div>
                </div>
                <div className="block-bottom">
                    <div className="actions-accept">
                        <button
                            className="btn btn-default btn-cannel"
                            type="button"
                            onClick={() => actions.checkoutToSelectPayments(quote)}>
                            {t('Back')}
                        </button>
                        <button
                            className={"btn btn-default btn-accept" + (!canUsePoint ? 'disabled' : '')}
                            type="button"
                            onClick={() => this.clickUsePoints()}>
                            {t('Use {{usePoint}} {{pointName}}', {
                                usePoint: NumberHelper.formatDisplayGroupAndDecimalSeparator(usePoint),
                                pointName: pointName
                            })}
                        </button>
                    </div>
                </div>
            </div>
        );
    }
}

class AmastySpendRewardPointContainer extends CoreContainer {
    static className = 'AmastySpendRewardPointContainer';

    /**
     * Map state to props
     * @param state
     * @returns {{quote: *}}
     */
    static mapState(state) {
        let {quote} = state.core.checkout;
        const availablePointBalance = AmastyRewardsService.getCustomerPointBalance(quote.customer);
        return {
            quote,
            availablePointBalance
        };
    }

    /**
     * Map dispatch to props
     /**
     *
     * @param dispatch
     * @return {{actions: {checkoutToSelectPayments: function(*=): *}}}
     */
    static mapDispatch(dispatch) {
        return {
            actions: {
                checkoutToSelectPayments: (quote, initPayments) => dispatch(
                    CheckoutAction.checkoutToSelectPayments(quote, initPayments)
                ),
                setQuote: (quote) => dispatch(QuoteAction.setQuote(quote)),
            }
        }
    }
}

/**
 *
 * @type {AmastySpendRewardPointContainer}
 */
const container = ContainerFactory.get(AmastySpendRewardPointContainer);
export default container.withRouter(
    ComponentFactory.get(AmastySpendRewardPointComponent)
)



