import AmastyRewardsHelper from "../../../../helper/AmastyRewardsHelper";

/**
 * Plugin to navigate menu for Amasty Reward Point Page
 */
export default {
    canUseMenuToggle: {
        amasty_rewards: {
            sortOrder: 100,
            disabled: false,
            after: function(result) {
                if (AmastyRewardsHelper.isEnabledAmastyRewards() && result) {
                    let AmastySpendRewardPoint = require("../../../../view/component/checkout/AmastySpendRewardPoint").default;
                    return this.props.currentPage !== AmastySpendRewardPoint.className;
                }
                return result;
            },
        }
    },
    canBackToCatalog: {
        amasty_rewards: {
            sortOrder: 100,
            disabled: false,
            after: function(result) {
                if (AmastyRewardsHelper.isEnabledAmastyRewards() && !result) {
                    let AmastySpendRewardPoint = require("../../../../view/component/checkout/AmastySpendRewardPoint").default;
                    const {currentPage, hasPaidOrWaitingGatewayPayment} = this.props;
                    return currentPage === AmastySpendRewardPoint.className
                        && !hasPaidOrWaitingGatewayPayment;
                }
                return result;
            },
        }
    },
    clickBackButton: {
        amasty_rewards: {
            sortOrder: 100,
            disabled: false,
            after: function(result) {
                const { actions, currentPage } = this.props;
                return () => {
                    let action = result();
                    let AmastySpendRewardPoint = require("../../../../view/component/checkout/AmastySpendRewardPoint").default;
                    if (AmastyRewardsHelper.isEnabledAmastyRewards()
                        && undefined === action
                        && currentPage === AmastySpendRewardPoint.className
                    ) {
                        return actions.switchPage('Payment');
                    }
                    return action;
                }
            },
        }
    },
};



