import {listen} from "../../../../../event-bus";
import AmastyRewardsHelper from "../../../helper/AmastyRewardsHelper";
import StatusConstant from "../../../../../view/constant/order/StatusConstant";
import NumberHelper from "../../../../../helper/NumberHelper";

export default class CheckoutServiceObserver {
    /**
     * constructor
     */
    constructor() {
        listen(
            'service_checkout_place_order_create_action_log_params_after',
            (eventData) => {
                /** in case use amasty reward */
                let {params} = eventData;
                if (
                    AmastyRewardsHelper.isEnabledAmastyRewards()
                    && params.order
                    && params.order.extension_attributes
                ) {
                    let order = JSON.parse(JSON.stringify(params.order));
                    delete order.extension_attributes.am_earn_reward_points;

                    order.addresses.map(address => {
                        if (address.extension_attributes) {
                            delete address.extension_attributes.am_earn_reward_points;
                        }
                        return address;
                    });

                    order.items.map(item => {
                        if (item.extension_attributes) {
                            delete item.extension_attributes.am_earn_reward_points;
                        }
                        return item;
                    });
                    params.order = order;
                }
            },
            'amasty_rewards'
        );

        listen(
            'checkout-place-order-before',
            (eventData) => {
                /** in case use amasty reward */
                let {order} = eventData;
                if (
                    AmastyRewardsHelper.isEnabledAmastyRewards()
                    && order.extension_attributes
                    && order.state !== StatusConstant.STATE_COMPLETE
                ) {
                    delete order.extension_attributes.am_earn_reward_points;

                    order.addresses.map(address => {
                        if (address.extension_attributes) {
                            delete address.extension_attributes.am_earn_reward_points;
                        }
                        return address;
                    });

                    order.items.map(item => {
                        if (item.extension_attributes) {
                            delete item.extension_attributes.am_earn_reward_points;
                        }
                        return item;
                    });
                }
            },
            'amasty_rewards'
        );

        listen(
            'service_checkout_place_order_after',
            (eventData) => {
                /** in case use amasty reward */
                let {order} = eventData;
                if (
                    AmastyRewardsHelper.isEnabledAmastyRewards()
                    && order.extension_attributes
                    && order.customer_id
                ) {
                    // eslint-disable-next-line
                    let AmastyRewardCustomerService =
                        require("../../../service/customer/AmastyRewardCustomerService").default;
                    let point = -order.extension_attributes.am_spent_reward_points;
                    if (order.state === StatusConstant.STATE_COMPLETE) {
                        point = NumberHelper.addNumber(point, order.extension_attributes.am_earn_reward_points);
                    }
                    AmastyRewardCustomerService.rewardCustomerWithPoint(
                        order.customer_id,
                        point
                    );
                }
            },
            'amasty_rewards'
        );
    }
}



