import OrderConstant from '../../../../../view/constant/OrderConstant';
import {Observable} from 'rxjs';
import RewardPointService from "../../../service/RewardPointService";
import EpicFactory from "../../../../../framework/factory/EpicFactory";
import {RewardPointHelper} from "../../../helper/RewardPointHelper";

/**
 * Receive action type(PLACE_ORDER_AFTER) and request, response list product
 * @param action$
 */
function RewardPointOrderPlaceOrderAfterEpic(action$) {
    return action$.ofType(OrderConstant.PLACE_ORDER_AFTER)
        .mergeMap(action => {
            if (!RewardPointHelper.isEnabledRewardPoint()) {
                return Observable.empty();
            }
            // check and remove used reward point
            const order = action.order;
            if (order.customer_id) {
                RewardPointService.removeUsedPoint();
            }
            return Observable.empty();
        });
}

RewardPointOrderPlaceOrderAfterEpic.className = 'RewardPointOrderPlaceOrderAfterEpic';

export default EpicFactory.get(RewardPointOrderPlaceOrderAfterEpic);



