import CoreService from "../../CoreService";
import ServiceFactory from "../../../framework/factory/ServiceFactory";
import QuoteItemService from "../../checkout/quote/ItemService";
import NumberHelper from "../../../helper/NumberHelper";
import TaxHelper from "../../../helper/TaxHelper";

class GiftcardRedeemCalculationService extends CoreService {
    static className = 'GiftcardRedeemCalculationService';
    giftCodeItemsTotal = {};

    initTotals(quote, items, giftcodes, isApplyGiftAfterTax = false) {
        this.giftCodeItemsTotal = {};
        giftcodes.forEach(giftcode => {
            let totalItemsPrice = 0,
                totalBaseItemsPrice = 0,
                validItemsCount = 0;
            items.forEach(item => {
                /*Skipping child items to avoid double calculations*/
                if (item.parent_item_id) {
                    return false;
                }
                if (!giftcode.valid_item_ids.includes(+item.item_id)) {
                    return false;
                }
                if (item.has_children && QuoteItemService.isChildrenCalculated(item, quote)) {
                    QuoteItemService.getChildrenItems(quote, item).forEach(child => {
                        let totalItemPrice = this.getTotalItemPrice(quote, child, isApplyGiftAfterTax);
                        totalItemsPrice = NumberHelper.addNumber(totalItemsPrice, totalItemPrice.item_price);
                        totalBaseItemsPrice = NumberHelper.addNumber(totalBaseItemsPrice, totalItemPrice.base_item_price);
                    });
                } else {
                    let totalItemPrice = this.getTotalItemPrice(quote, item, isApplyGiftAfterTax);
                    totalItemsPrice = NumberHelper.addNumber(totalItemsPrice, totalItemPrice.item_price);
                    totalBaseItemsPrice = NumberHelper.addNumber(totalBaseItemsPrice, totalItemPrice.base_item_price);
                }
                validItemsCount++;
            });
            this.giftCodeItemsTotal[giftcode.code] = {
                items_price: totalItemsPrice,
                base_items_price: totalBaseItemsPrice,
                items_count: validItemsCount
            };
        });
    }

    /**
     * Get Total Item Price
     *
     * @param quote
     * @param item
     * @param isApplyGiftAfterTax
     * @returns {{item_price: *, base_item_price: *}}
     */
    getTotalItemPrice(quote, item, isApplyGiftAfterTax) {
        let totalItemPrice = 0;
        let totalBaseItemPrice = 0;
        let qty = QuoteItemService.getTotalQty(item, quote);

        let totalItemPriceQty = NumberHelper.multipleNumber(this.getItemPrice(item), qty);
        totalItemPriceQty = NumberHelper.minusNumber(totalItemPriceQty, item.discount_amount);
        totalItemPrice = NumberHelper.addNumber(totalItemPrice, totalItemPriceQty);

        let baseTotalItemPriceQty = NumberHelper.multipleNumber(this.getItemBasePrice(item), qty);
        baseTotalItemPriceQty = NumberHelper.minusNumber(baseTotalItemPriceQty, item.base_discount_amount);
        totalBaseItemPrice = NumberHelper.addNumber(totalBaseItemPrice, baseTotalItemPriceQty);

        if (isApplyGiftAfterTax && !TaxHelper.discountTax()) {
            totalItemPrice = NumberHelper.addNumber(totalItemPrice, item.tax_amount);
            totalBaseItemPrice = NumberHelper.addNumber(totalBaseItemPrice, item.base_tax_amount);
        } else if (!isApplyGiftAfterTax && !TaxHelper.discountTax()) {
            totalItemPrice = NumberHelper.minusNumber(totalItemPrice, item.tax_amount);
            totalBaseItemPrice = NumberHelper.minusNumber(totalBaseItemPrice, item.base_tax_amount);
        }
        return {
            item_price: totalItemPrice,
            base_item_price: totalBaseItemPrice
        };
    }

    /**
     * Get gift code items total
     *
     * @param code
     * @return {*|null}
     */
    getGiftCodeItemsTotal(code) {
        return this.giftCodeItemsTotal[code] || null;
    }

    /**
     * Get Item base price
     *
     * @param item
     * @return number
     */
    getItemBasePrice(item) {
        let basePrice = item.base_discount_calculation_price;
        let baseCalcPrice = QuoteItemService.getBaseCalculationPrice(item);
        /* If item doesn't have base_discount_calculation_price, return base calculation price
        * else return base_discount_calculation_price */
        return basePrice === null || basePrice === undefined ? baseCalcPrice : basePrice;
    }

    /**
     * Get Item base price
     *
     * @param item
     * @return number
     */
    getItemPrice(item) {
        let price = item.discount_calculation_price;
        let calcPrice = QuoteItemService.getCalculationPrice(item);
        /* If item doesn't have discount_calculation_price, return base calculation price
        * else return discount_calculation_price */
        return price === null || price === undefined ? calcPrice : price;
    }
}

/**
 * @type {GiftcardRedeemCalculationService}
 */
let giftcardRedeemCalculationService = ServiceFactory.get(GiftcardRedeemCalculationService);

export default giftcardRedeemCalculationService;


