import LogoutPopupConstant from "../../../../../view/constant/LogoutPopupConstant";
import AmastyRewardsConstant from "../../constant/AmastyRewardsConstant";

const initialState = {isCheckingEarnPoint: false};

const amastyEarningReducer = function (state = initialState, action) {
    switch (action.type) {
        case AmastyRewardsConstant.CHECK_EARNING_POINT: {
            return {
                ...state,
                isCheckingEarnPoint: true
            };
        }
        case AmastyRewardsConstant.CHECK_EARNING_POINT_RESULT: {
            return {
                ...state,
                isCheckingEarnPoint: false
            };
        }
        case LogoutPopupConstant.FINISH_LOGOUT_REQUESTING:
            return {...state, isCheckingEarnPoint: false};
        default:
            return state
    }
};

export default amastyEarningReducer;



