import {listen} from "../../../../event-bus";

export default class SingletonObserver {
    /**
     * constructor
     */
    constructor() {
        listen('constructor_singleton_before', (eventData) => {
            let {resources} = eventData;
            let {OmcAmastyRewards} = require('../../data/omc/index');
            resources.OmcAmastyRewards = OmcAmastyRewards;
        }, 'amasty_rewards');
    }
}



