import AmastyRewardsHelper from "../../../helper/AmastyRewardsHelper";

/**
 * Plugin to add processor to quote service
 */
export default {
    convertQuoteDataToOrder: {
        amasty_rewards: {
            sortOrder: 100,
            disabled: false,
            after: function(order, quote) {
                if (!AmastyRewardsHelper.isEnabledAmastyRewards()) {
                    return order;
                }
                if (quote.amasty_rewards_quote_id) {
                    order.quote_id = quote.amasty_rewards_quote_id;
                }
                
                return order;
            },
        }
    },
};



