import ConfigHelper from "../../../helper/ConfigHelper";

export default {
    /**
     * Is Enabled Amasty Rewards
     *
     * @return {number}
     */
    isEnabledAmastyRewards() {
        return Number(ConfigHelper.getConfig('amrewards/general/enabled') || 0);
    },

    /**
     * Get Balance Label
     *
     * @returns {*|string}
     */
    getBalanceLabel() {
        return ConfigHelper.getConfig('amrewards/customer/balance_label') || "Reward Points";
    },

    /**
     * Return true, when rewards cannot be earned by order using reward points.
     *
     * @returns {boolean}
     */
    isDisabledEarningByRewards() {
        return !!Number(ConfigHelper.getConfig('amrewards/points/disable_reward') || 0);
    },

    /**
     * Get Spending Rate
     *
     * @returns {number}
     */
    getSpendingRate() {
        return Number(ConfigHelper.getConfig('amrewards/points/rate'));
    },

    /**
     * Get Spending Rate
     *
     * @returns {string}
     */
    getEarningCalculationMode() {
        return ConfigHelper.getConfig('amrewards/calculation/before_after_tax');
    },

    /**
     * Get Minimum Points Requirement
     *
     * @returns {number}
     */
    getMinimumPointsRequirement() {
        return Number(ConfigHelper.getConfig('amrewards/points/minimum_reward') || 0);
    },

    /**
     * Get Redemption Limit Type
     *
     * @returns {number}
     */
    getRedemptionLimitType() {
        return Number(ConfigHelper.getConfig('amrewards/points/enable_limit'));
    },

    /**
     * Get Redemption Limit Amount
     *
     * @returns {number}
     */
    getRedemptionLimitAmount() {
        return Number(ConfigHelper.getConfig('amrewards/points/limit_amount_reward'));
    },

    /**
     * Get Redemption Limit Percent
     *
     * @returns {number}
     */
    getRedemptionLimitPercent() {
        return Number(ConfigHelper.getConfig('amrewards/points/limit_percent_reward'));
    },

    /**
     * Is Specific Products Enabled
     *
     * @returns {boolean}
     */
    isSpecificProductsEnabled() {
        return !!Number(ConfigHelper.getConfig('amrewards/spending_config/specific_products_enabled') || 0);
    },

    /**
     * Get Specific Products Action
     *
     * @returns {number}
     */
    getSpecificProductsAction() {
        return Number(ConfigHelper.getConfig('amrewards/spending_config/action'));
    },

    /**
     * Get Specific Products Sku
     *
     * @returns {*[]}
     */
    getSpecificProductsSku() {
        let stringOfSku = ConfigHelper.getConfig('amrewards/spending_config/sku');
        let skus = [];
        if (stringOfSku) {
            skus = stringOfSku.split(',').map(sku => sku.trim());
        }
        return skus;
    },

    /**
     * Get Specific Products Categories
     *
     * @returns {*[]}
     */
    getSpecificProductsCategories() {
        let stringOfCategories = ConfigHelper.getConfig('amrewards/spending_config/category');
        let categories = [];
        if (stringOfCategories) {
            categories = stringOfCategories.split(',').map(category => category.trim());
        }
        return categories;
    },

    /**
     * Get Round Rule
     *
     * @returns {*}
     */
    getRoundRule() {
        return ConfigHelper.getConfig('amrewards/points/round_rule');
    },

    /**
     * Is Show Detailed Info In Order Detail
     *
     * @returns {boolean}
     */
    isShowDetailedInfoInOrderDetail() {
        return !!Number(ConfigHelper.getConfig('amrewards/order/show_detailed') || 0);
    },

    /**
     * Is Read Only Credit Memo Fields
     *
     * @returns {boolean}
     */
    isReadOnlyCreditMemoFields() {
        return !!Number(ConfigHelper.getConfig('amrewards/points/read_only') || 0);
    }
}



