import EpicFactory from "../../../../../framework/factory/EpicFactory";
import LogConstant from "../../../../constant/log/LogConstant";
import LogService from "../../../../../service/log/LogService";
import CheckoutConstant from "../../../../constant/CheckoutConstant";
import UserService from "../../../../../service/user/UserService";
import {Observable} from "rxjs";
import PosService from "../../../../../service/PosService";
import ProcessLogConstant from "../../../../constant/log/ProcessLogConstant";

function LogCheckoutProcessSinglePaymentResultEpic(action$, store) {
    return action$.ofType(CheckoutConstant.CHECKOUT_PROCESS_SINGLE_PAYMENT_RESULT)
        .mergeMap((action) => {
            let {result, payment, index} = action;
            let quote = store.getState().core.checkout.quote;
            quote = LogService.cloneAndFilterQuoteData(quote);
            let log = {
                [LogConstant.LOG_TYPE]: LogConstant.PROCESS,
                [LogConstant.LOG_FLOW]: LogConstant.FLOW_PLACE_ORDER,
                [LogConstant.BUSINESS_FLOW]: LogConstant.BUSINESS_FLOW_PROCESS_PAYMENT,
                [LogConstant.USER_TYPE]: LogConstant.USER_TYPE_STAFF,
                [LogConstant.USER_EMAIL]: UserService.getStaffEmail(),
                [LogConstant.USER_NAME]: UserService.getStaffName(),
                [LogConstant.LOG_MESSAGE]: "Process payment result (" + payment.method + ") #" + payment.increment_id
                    + " - Quote #" + quote.id + " - Pos: " + PosService.getCurrentPosName(),
                [ProcessLogConstant.PROCESS_TYPE]: ProcessLogConstant.PROCESS_TYPE_BUSINESS,
                [ProcessLogConstant.PROCESS_NAME]: 'Process payment result',
                [ProcessLogConstant.PROCESS_INPUT]: {
                    quote: quote,
                    payment: LogService.cloneAndFilterPaymentData(payment),
                    index: index,
                    result: result
                }
            };
            LogService.saveLog(log);
            return Observable.empty();
        });
}

LogCheckoutProcessSinglePaymentResultEpic.className = 'LogCheckoutProcessSinglePaymentResultEpic';

export default EpicFactory.get(LogCheckoutProcessSinglePaymentResultEpic);



