import OmcAbstract from "../../../../data/omc/OmcAbstract";

export default class OmcAmastyRewards extends OmcAbstract {
    static className = 'OmcAmastyRewards';

    check_earning_point = '/V1/webposAmastyRewards/checkEarningPoint';

    /**
     * Check earning point
     *
     * @param params
     * @returns {Promise<*>}
     */
    checkEarningPoint(params) {
        let url = this.getBaseUrl() + this.check_earning_point;
        return this.post(url, params);
    }
}



