import AmastyRewardsHelper from "../../../../../../helper/AmastyRewardsHelper";

/**
 * Plugin to add cart total for spend amasty reward point page
 */
export default {
    template: {
        amasty_rewards: {
            sortOrder: 100,
            disabled: false,
            before: function() {
                let AmastySpendRewardPoint = require("../../../../../../view/component/checkout/AmastySpendRewardPoint").default;
                if (AmastyRewardsHelper.isEnabledAmastyRewards()
                    && !this.showOnPages.includes(AmastySpendRewardPoint.className)
                ) {
                    this.showOnPages.push(AmastySpendRewardPoint.className);
                }
            },
        }
    },
};



