import {AbstractTotalService} from "../../../../../service/checkout/quote/total/AbstractService";
import ServiceFactory from "../../../../../framework/factory/ServiceFactory";
import AmastyRewardsService from "../../../service/AmastyRewardsService";
import AmastyRewardsHelper from "../../../helper/AmastyRewardsHelper";
import CurrencyHelper from "../../../../../helper/CurrencyHelper";
import NumberHelper from "../../../../../helper/NumberHelper";
import AmastySpendingCheckerService from "../AmastySpendingCheckerService";
import TaxHelper from "../../../../../helper/TaxHelper";
import AmastyRewardsConstant from "../../../view/constant/AmastyRewardsConstant";
import i18n from "../../../../../config/i18n";

export class AmastyPointTotalService extends AbstractTotalService {
    static className = 'AmastyPointTotalService';

    code = "amasty_rewards";

    /**
     * Collect point discount
     *
     * @param quote
     * @param address
     * @param total
     * @returns {AmastyPointTotalService}
     */
    collect(quote, address, total) {
        super.collect(quote, address, total);
        if (!quote.customer
            || (!quote.is_virtual && address.address_type === 'billing')
            || (quote.is_virtual && address.address_type === 'shipping')
            || !AmastyRewardsHelper.isEnabledAmastyRewards()
        ) {
            return this;
        }

        let maxPoints = AmastyRewardsService.getMaximumOfRedeemableForQuote(quote);
        if (!maxPoints || !AmastyRewardsService.customerCanSpendPoint(quote.customer)) {
            return this;
        }

        let spentPoints = Math.min(AmastyRewardsService.getUsedPoint(), maxPoints);
        let appliedPoints = this.calculateDiscount(quote, total, spentPoints);

        if (appliedPoints) {
            this.setAppliedPoints(total, quote, address, appliedPoints);
        }
        return this;
    }

    /**
     * Calculate Discount
     *
     * @param quote
     * @param total
     * @param points
     * @returns {number}
     */
    calculateDiscount(quote, total, points) {
        let rate = AmastyRewardsHelper.getSpendingRate();
        let items = this.filterItems(quote);
        let allCartPrice = this.getAllItemsPrice(items);
        if (!points || !rate || !items.length || !allCartPrice) {
            return 0;
        }

        items = this.sortItems(items);

        let roundRule = AmastyRewardsHelper.getRoundRule();
        let basePointsDiscount = AmastyRewardsService.convertPointToMoney(points, allCartPrice);
        let percent = (basePointsDiscount / allCartPrice) * 100;
        let discountValue = 0;

        items.forEach((item, index) => {
            let baseItemPrice = this.calculateItemAmount(item);
            let baseItemPointsDiscount = NumberHelper.multipleNumber(baseItemPrice, percent) / 100;
            basePointsDiscount = NumberHelper.minusNumber(basePointsDiscount, baseItemPointsDiscount);
            if (index === (items.length - 1)) {
                baseItemPointsDiscount = NumberHelper.addNumber(baseItemPointsDiscount, basePointsDiscount);
            }
            discountValue = NumberHelper.addNumber(discountValue, baseItemPointsDiscount);
            if (!item.extension_attributes) {
                item.extension_attributes = {};
            }
            let itemPoints = NumberHelper.multipleNumber(baseItemPointsDiscount, rate);
            item.extension_attributes.am_spent_reward_points = NumberHelper.addNumber(
                Number(item.extension_attributes.am_spent_reward_points || 0),
                itemPoints
            );
            item.base_discount_amount = NumberHelper.addNumber(
                Number(item.base_discount_amount || 0),
                baseItemPointsDiscount
            );
            let itemPointsDiscount = CurrencyHelper.convertAndRoundToFloat(baseItemPointsDiscount);
            item.discount_amount = NumberHelper.addNumber(
                Number(item.discount_amount || 0),
                itemPointsDiscount
            );
            this._addAmount(-(itemPointsDiscount || 0), 'discount');
            this._addBaseAmount(-(baseItemPointsDiscount || 0), 'discount');
        });

        let appliedPoints = NumberHelper.multipleNumber(discountValue, rate);
        if (roundRule === AmastyRewardsConstant.ROUND_RULE_UP) {
            appliedPoints = Math.ceil(appliedPoints);
        }
        return Number(appliedPoints);
    }

    /**
     * Sort Items
     *
     * @param items
     * @returns {*}
     */
    sortItems(items) {
        return items.sort((a, b) => {
            let aRealItemPrice = this.getRealItemPrice(a);
            let bRealItemPrice = this.getRealItemPrice(b);
            if (aRealItemPrice > bRealItemPrice) {
                return 1;
            }
            if (aRealItemPrice < bRealItemPrice) {
                return -1;
            }
            return 0;
        });
    }

    /**
     * Calculate Item Amount
     *
     * @param item
     * @returns {number}
     */
    calculateItemAmount(item) {
        let itemPrice = item.base_price_incl_tax;
        if (!TaxHelper.discountTax()) {
            itemPrice = item.base_price;
        }
        let amount = NumberHelper.minusNumber(
            NumberHelper.multipleNumber(itemPrice, item.qty),
            item.base_discount_amount
        )
        return Number(Math.max(0, amount));
    }

    /**
     * Filter Items
     *
     * @param quote
     * @returns {*[]}
     */
    filterItems(quote) {
        let filteredItems = [];
        quote.items.forEach(item => {
            if (AmastySpendingCheckerService.isPossibleSpendOnItem(quote, item)) {
                filteredItems.push(item);
            }
        });
        return filteredItems;
    }

    /**
     * Get All Items Price
     *
     * @param items
     * @returns {number}
     */
    getAllItemsPrice(items) {
        let allItemsPrice = 0;

        items.forEach(item => {
            allItemsPrice = NumberHelper.addNumber(allItemsPrice, this.getRealItemPrice(item));
        });

        return Number(allItemsPrice);
    }

    /**
     * Get Real Item Price
     *
     * @param item
     * @returns {number}
     */
    getRealItemPrice(item) {
        let itemPrice = item.base_price_incl_tax;
        if (!TaxHelper.discountTax()) {
            itemPrice = item.base_price;
        }
        let realPrice = NumberHelper.minusNumber(
            NumberHelper.multipleNumber(itemPrice, item.qty),
            item.base_discount_amount
        );
        return Number(Math.max(0, realPrice));
    }

    /**
     * Set Applied Points
     *
     * @param total
     * @param quote
     * @param address
     * @param usedPoint
     */
    setAppliedPoints(total, quote, address, usedPoint) {
        if (!address.discount_description) {
            address.discount_description = {};
        }
        address.discount_description.amrewards = i18n.translator.translate(
            "Used {{usedPoints}} reward points",
            {
                usedPoints: usedPoint
            }
        );
        if (typeof total.extension_attributes === 'undefined') {
            total.extension_attributes = {};
        }
        total.extension_attributes.am_spent_reward_points = NumberHelper.addNumber(
            Number(total.extension_attributes.am_spent_reward_points || 0),
            usedPoint
        );
        total.base_subtotal_with_discount = NumberHelper.addNumber(
            Number(total.base_subtotal || 0),
            Number(total.base_discount_amount || 0)
        );
        total.subtotal_with_discount = NumberHelper.addNumber(
            Number(total.subtotal || 0),
            Number(total.discount_amount || 0)
        );

        quote.extension_attributes.am_spent_reward_points = total.extension_attributes.am_spent_reward_points;
    }
}

/** @type {AmastyPointTotalService} */
let amastyPointTotalService = ServiceFactory.get(AmastyPointTotalService);

export default amastyPointTotalService;



