import React from "react";
import AmastyRewardsHelper from "../../../../helper/AmastyRewardsHelper";

export default {
    block_refund_adjustments_after: [
        function templateRefundPoint(component) {
            const {order} = component.props;
            // eslint-disable-next-line
            let AdjustPointComponent = require("../../../../view/component/order/order-detail/create-creditmemo/step-adjustment/CreateCreditmemoStepAdjustAmastyPointAdjustments").default;
            if (AmastyRewardsHelper.isEnabledAmastyRewards()
                && order.customer_id
                && !order.customer_is_guest
                && (
                    order.extension_attributes.am_spent_reward_points
                    || order.extension_attributes.am_earn_reward_points
                )
            ) {
                return (
                    <div className="block-refund-point" key="block-refund-point">
                        <AdjustPointComponent order={component.props.order}
                                              creditmemo={component.props.creditmemo}
                                              adjustments={component.props.adjustments}
                                              changeAdjustment={component.props.changeAdjustment}
                                              setCreditmemo={component.props.setCreditmemo}
                                              getCreditmemo={component.props.getCreditmemo}
                        />
                    </div>
                );
            }
            return null;
        }
    ],
}



