import React, {Fragment} from 'react';
import ProductImage from '../../style/images/product_placeholder.png';
import {injectGlobal} from "styled-components";
import LocalStorageHelper from '../../../helper/LocalStorageHelper';
import ProductTypeConstant from '../../constant/ProductTypeConstant';
import {RewardPointHelper} from "../../../extension/reward-points/helper/RewardPointHelper";
import TaxHelper from '../../../helper/TaxHelper';
import CurrencyHelper from "../../../helper/CurrencyHelper";
import '../../style/css/SecondDisplay.css'
import NumberHelper from "../../../helper/NumberHelper";
import layout from "../../../framework/Layout";
import _ from "lodash";
import GiftcardHelper from "../../../helper/GiftcardHelper";
import PaymentHelper from "../../../helper/PaymentHelper";
import i18n from "../../../config/i18n";
import LoadingImage from "../../style/images/loading.gif";
import {CustomDiscountService} from "../../../service/checkout/quote/CustomDiscountService";
import CoreComponent from "../../../framework/component/CoreComponent";
import CoreContainer from "../../../framework/container/CoreContainer";
import ContainerFactory from "../../../framework/factory/ContainerFactory";
import ComponentFactory from "../../../framework/factory/ComponentFactory";
import QuoteItemService from "../../../service/checkout/quote/ItemService";
import Loading from "../../../view/component/loading/Loading";
import WeeeDataService from "../../../service/weee/WeeeDataService";
import ShippingComponent from "../../../view/component/checkout/shipping/Shipping";
import TaxComponent from "../../../view/component/checkout/cart/totals/Tax";
import GiftCard from "../../../view/component/checkout/cart/totals/GiftCard";
import EarnPoint from "../../../extension/reward-points/view/component/checkout/cart/totals/EarnPoint";

/*
 * Hide header left button
 */
const HideMenuButton = () => injectGlobal`
    .wrapper-menu,.fixed-wrapper-header {
        display: none !important;
    }        
`;
/*
 * Show header left button
 */
const ShowMenuButton = () => injectGlobal`
    .wrapper-menu,.fixed-wrapper-header {
        display: flex !important;
    }        
`;
export default function () {
    class SecondDisplayComponent extends CoreComponent {
        static className = 'SecondDisplayComponent';

        constructor(props) {
            super(props);
            this.totals = [];
            this.screenElement = null;
            this.isFullScreen = false;
            this.state = {
                quote: {},
                imageSize: '',
            }
        }

        /**
         * on did mount, set value in first and in event listener
         */
        componentDidMount() {
            this.getLocalStorageValue();
            this.getImageSize();
            this.getScreen();
            window.addEventListener('storage', () => {
                this.getLocalStorageValue()
            });
            window.addEventListener('keydown', (event) => {
                if (event.code === 'KeyF' && this.screenElement) {
                    if (!this.isFullScreen) {
                        this.screenElement.requestFullscreen().then(() => {
                            this.isFullScreen = true
                        })
                    } else {
                        document.exitFullscreen().then(() => {
                            this.isFullScreen = false
                        })
                    }
                }
            });

            this.backDrop = document.createElement("div");
            this.backDrop.className = "modal-backdrop  in popover-backdrop";
            this.backDrop.style.display = "none";
            this.backDrop.onclick = () => this.hideBackDrop();
            document.body.appendChild(this.backDrop);
        }

        /**
         *  Show back drop when display coupon code popover
         *
         * @return
         */
        showBackDrop() {
            this.backDrop.style.display = "block";
        }

        hideBackDrop() {
            this.backDrop.click();
            this.backDrop.style.display = "none";
        }

        // eslint-disable-next-line
        componentDidUpdate(prevProps, prevState, snapshot) {
            this.getScreen()
        }

        /**
         * on unmount, remove event
         */
        componentWillUnmount() {
            ShowMenuButton();
            window.removeEventListener('storage', () => {
            });
            window.removeEventListener('keydown', () => {
            });
        }

        /*
         * get window to full screen
         */
        getScreen() {
            const findNode = setInterval(() => {
                const screenElement = document.querySelector('#second-display');
                if (screenElement) {
                    this.screenElement = screenElement;
                    clearInterval(findNode);
                }
            }, 500)
        }

        /*
         * get the desired image dimensions
         */
        getImageSize() {
            const findNode = setInterval(() => {
                const leftPanel = document.querySelector('.left-panel');
                if (leftPanel) {
                    this.setState({
                        imageSize: '[' + leftPanel.clientWidth + ' x ' + leftPanel.clientHeight + ']'
                    });
                    clearInterval(findNode);
                }
            }, 500);
        }

        /**
         * get local storage to set state
         */
        getLocalStorageValue() {
            const quote = LocalStorageHelper.get("quote");
            this.setState({quote: JSON.parse(quote)});
        }

        /**
         * Get product image to show in cart item
         *
         * @return {string}
         */
        getProductImage(product) {
            let productImage = product.image;
            if (!productImage) {
                productImage = ProductImage;
            }
            if (
                productImage.includes('http://') &&
                window.location.href.includes('https://')
            ) {
                productImage.replace('http://', 'https://');
            }
            return productImage;
        }

        /**
         *  Add data to totals
         *
         * @param code
         * @param title
         * @param value
         * @param unit
         * @return rules
         */
        addToTotals(code, title, value, unit) {
            this.totals.push({
                code: code,
                title: title,
                value: value,
                unit: unit,
            });
        }

        /**
         * get option detail like as custom, bundle, configurable option
         * @param item
         * @return {*}
         */
        displayOption(item) {
            if (
                item.product_type === ProductTypeConstant.SIMPLE
                || item.product_type === ProductTypeConstant.VIRTUAL
            ) {
                return this.displayCustomOption(item);
            }
            if (item.product_type === ProductTypeConstant.CONFIGURABLE) {
                let result = [];
                result.push(this.displayConfigurableOption(item));
                result.push(this.displayCustomOption(item));

                return result;
            }

            if (item.product_type === ProductTypeConstant.BUNDLE) {
                return this.displayBundleOption(item);
            }

            return null;
        }

        /**
         * display custom options
         * @param item
         * @return {Array}
         */
        displayCustomOption(item) {
            let result = [];
            let customOptions = item.product_options && item.product_options.options ?
                item.product_options.options : [];
            customOptions.map(option => {
                return result.push(
                    <span className="bundle-item-option item-option" key={option.option_id}>
                    {`${option.label}: ${option.value}`}
                </span>
                )
            });
            return result;
        }

        /**
         * Display option of configurable item
         *
         * @param item
         * @return {*}
         */
        displayConfigurableOption(item) {
            if (!item['product_options']) return '';
            const {attributes_info} = item['product_options'];
            if (!attributes_info) return '';
            const options = attributes_info.map(attribute_info => {
                return `${attribute_info.label}: ${attribute_info.value}`;
            });
            return <span className="item-option" key={Math.random()}>{options.join('; ')}</span>;
        }

        /**
         * Display option of bundle item
         *
         * @param item
         * @return {Array}
         */
        displayBundleOption(item) {
            let result = [];
            let bundleOptions = item.product_options && item.product_options.bundle_options ?
                item.product_options.bundle_options : [];
            let index = 0;
            Object.keys(bundleOptions).map(key => {
                if (bundleOptions[key].value && bundleOptions[key].value.length) {
                    result.push(bundleOptions[key].value.map(value => {
                        return <span className="bundle-item-option item-option" key={index++}>
                            {value.qty + ' x ' + value.title}
                        </span>;
                    }));
                }
                return key;
            });
            return result;
        }

        /**
         *  Prepare totals data for render
         *
         * @return rules
         */
        prepareTotals(quote) {
            let items = quote.items;
            this.totals = [];
            let subTotal = quote.subtotal;


            // let eventDataPrepareBefore = {pointDiscount: pointDiscount, cartTotal: this};
            let pointDiscount = -quote.rewardpoints_discount;

            let giftcardDiscount = null;
            if (quote.gift_voucher_gift_codes) {
                giftcardDiscount = quote.gift_voucher_discount !== null &&
                typeof quote.gift_voucher_discount !== 'undefined' ? quote.gift_voucher_discount : null;
            }

            if (TaxHelper.shoppingCartDisplaySubtotalIncludeTax()) {
                subTotal = quote.subtotal_incl_tax;
            }
            if (subTotal !== undefined) {
                this.addToTotals("subtotal", this.props.t('Subtotal'), subTotal, "");
            }
            let discount = quote.discount_amount - pointDiscount;
            if (giftcardDiscount !== null) {
                discount = NumberHelper.minusNumber(discount, -giftcardDiscount);
            }

            if (quote.coupon_code) {
                this.addToTotals(
                    "discount", this.props.t('Discount') + " (" + quote.coupon_code + ")", discount, ""
                );
            } else {
                this.addToTotals("discount", this.props.t('Discount'), discount, "");
            }

            if (!quote.is_virtual) {
                let shipping_amount = TaxHelper.shoppingCartDisplayShippingIncludeTax() ?
                    quote.shipping_incl_tax : quote.shipping_amount;
                this.addToTotals(
                    "shipping",
                    this.props.t(quote.shipping_method ? 'Shipping' : "Add Shipping"),
                    shipping_amount, ""
                );
            }

            let weeeTotal = WeeeDataService.getTotalAmounts(items, quote);
            if (weeeTotal) {
                this.addToTotals("weee", this.props.t('FPT'), weeeTotal || 0, "");
            }

            let taxAmount = quote.tax_amount;
            if (taxAmount || TaxHelper.displayZeroSubtotal()) {
                this.addToTotals("tax", this.props.t('Tax'), taxAmount || 0, "");
            }
            this.getRewardPointsDiscount(quote);

            let isShowGiftCardTotal = GiftcardHelper.isGiftcardEnable() &&
                !items.find(item => item.product_type === ProductTypeConstant.GIFT_CARD) && giftcardDiscount !== null;

            if (isShowGiftCardTotal) {
                this.addToTotals(
                    ProductTypeConstant.GIFT_CARD,
                    this.props.t("Gift Card"),
                    giftcardDiscount !== null ? -giftcardDiscount : null
                );
            }

            if (this.canShow()) {
                this.addToTotals("grand_total", this.props.t('Total'), quote.grand_total || 0, "");
            }
        }

        getCartHeader(quote) {
            return (
                <div className="cart-header-second-screen">
                    <div className="header-left-second-screen">
                        <div className="header-customer">
                            <strong className="title">
                                {this.props.t('Cart')}
                                {quote.items_qty ? '(' +
                                    NumberHelper.formatDisplayGroupAndDecimalSeparator(quote.items_qty) + ')' : ''}
                            </strong>
                        </div>
                    </div>
                </div>
            );
        }

        getCustomerName(quote) {
            let customer = quote.customer;
            if (customer && customer.id) {
                return customer.firstname + " " + customer.lastname;
            }
            return this.props.t('Guest');
        }

        getRewardPointsOfCustomer(quote) {
            const {customer} = quote;
            const pointName = RewardPointHelper.getPointName();
            const pluralOfPointName = RewardPointHelper.getPluralOfPointName();
            let isEnabledRewardPoint = RewardPointHelper.isEnabledRewardPoint();

            if (isEnabledRewardPoint
                && customer
                && customer.id
                && customer.extension_attributes
                && customer.extension_attributes.point_balance
            ) {
                return this.props.t('({{point}} {{pointLabel}})', {
                    point: NumberHelper.formatDisplayGroupAndDecimalSeparator(
                        customer.extension_attributes.point_balance
                    ),
                    pointLabel: customer.extension_attributes.point_balance > 1
                        ? pluralOfPointName
                        : pointName
                });
            }
            return '';
        }

        getCustomerButton(quote) {
            return (
                <Fragment>
                    <div className="customer-drop dropdown">
                        <a className={"dropdown-toggle disabled"}
                           data-toggle="modal" data-target="#popup-drop-customer"
                        >
                            {this.getCustomerName(quote)} &nbsp;
                            {this.getRewardPointsOfCustomer(quote)}
                        </a>
                    </div>
                </Fragment>
            );
        }

        getCartItems(quote) {
            let items = _.orderBy(quote.items, 'item_id', 'desc');
            return (
                <Fragment>
                    <ul className="minicart">
                        <div className={"minicart-content"}>
                            {
                                items.map((item, index = 0) => {
                                    return !item.parent_item_id &&
                                        this.getCartItem(item, quote)
                                })
                            }
                        </div>
                    </ul>
                </Fragment>
            )
        }

        getCartItem(item, quote) {
            let childItem = false;
            if (item.product_type === ProductTypeConstant.CONFIGURABLE) {
                childItem = QuoteItemService.getChildrenItems(quote, item)[0];
            }
            const realProduct = childItem ? childItem.product : item.product;
            return this.getContentCartItem(item, realProduct, quote);
        }

        getContentCartItem(item, product, quote) {
            let className = product.id < 0 ? "item-info item-customesale" : "item-info";
            let eventData = {
                className: className,
                item: item
            };
            className = eventData.className;

            return (
                <li className={'item ' + item.item_id} key={'item-' + item.item_id}>
                    <div className="swiper-container">
                        <div className="swiper-wrapper">
                            <div className="swiper-slide">
                                <div className={className}>
                                    {
                                        <Fragment>
                                            <div className="item-image">
                                                <div className="image">
                                                    <img className="lazyload" src=''
                                                         data-src={this.getProductImage(product)}
                                                         alt=""/>
                                                    <div
                                                        className={item.qty !== 1 ? 'qty' : 'hidden'}
                                                    >
                                                        {NumberHelper.formatDisplayGroupAndDecimalSeparator(item.qty)}
                                                    </div>
                                                </div>
                                            </div>
                                            <div className="item-detail">
                                                <span className="item-name"
                                                      dangerouslySetInnerHTML={{__html: item.name}}/>
                                                {this.displayOption(item)}
                                                {layout('checkout')('cart')('cart_item')('cart_item_itemdetail_after')()(this)}
                                            </div>
                                        </Fragment>
                                    }
                                    {
                                        <div className="item-price cannot-use-custom-price">
                                            <div className="price">{QuoteItemService.getDisplayPrice(item, quote)}</div>
                                            {QuoteItemService.showOriginalPrice(item, quote) &&
                                            <div
                                                className="original"> {QuoteItemService.getDisplayOriginalPrice(item, quote)}</div>
                                            }
                                        </div>
                                    }
                                </div>
                            </div>
                        </div>
                    </div>
                </li>
            )
        }

        getCartTotals(quote) {
            this.prepareTotals(quote);
            return (
                <div>
                    <div className="cart-totals"
                         style={{display: this.canShow() ? "block" : "none"}}>
                        <ul>
                            {this.getTemplateTotals(quote)}
                        </ul>
                    </div>
                </div>
            );
        }

        getTemplateTotals(quote) {
            let templateTotals = this.totals.map(total => this.getTemplateTotal(total, quote));
            return templateTotals;
        }

        /**
         *  Make tempate total by total data
         *
         * @param total
         * @return template total
         */
        getTemplateTotal(total, quote) {
            if (total.code === "discount") {
                let hasPaidOrWaitingGatewayPayment = PaymentHelper.hasPaidOrWaitingGatewayPayment(quote.payments);
                return  (this.getDiscountElement(quote, total, hasPaidOrWaitingGatewayPayment))
            } else if (total.code === "shipping") {
                if (quote.shipping_method) {
                    return <ShippingComponent key={total.code}
                                              quote={quote}
                                              total={total}
                                              showBackDrop={() => this.showBackDrop()}
                    />
                }
            } else if (total.code === "tax") {
                return <TaxComponent key={total.code}
                                     quote={quote}
                                     total={total}
                                     showBackDrop={() => this.showBackDrop()}
                />
            } else if (total.code === ProductTypeConstant.GIFT_CARD) {
                return <GiftCard key={total.code}
                                 quote={quote}
                                 total={total}
                                 showBackDrop={() => this.showBackDrop()}
                />
            } else if (total.code === "earn_point") {
                return <EarnPoint key={total.code}
                                  quote={this.props.quote}
                                  total={total}
                                  showBackDrop={() => this.showBackDrop()}
                />
            } else if(total.code === "spend_point") {
                let displayValue = `-${CurrencyHelper.format(Math.abs(total.value), false)}`;
                return (
                    <li className="totals-discount totals-action" >
                        <span className="mark">{total.title}</span>
                        <span className={"amount"}>{displayValue}</span>
                    </li>
                )
            } else {
                let displayValue = CurrencyHelper.format(Math.abs(total.value), null, null);
                return (
                    <Fragment key={total.code}>
                        <li className={total.code}>
                            <span className="mark">{total.title}</span>
                            <span className="amount">{displayValue}</span>
                        </li>
                    </Fragment>
                )
            }
        }

        getDiscountElement(quote, total, hasPaidOrWaitingGatewayPayment) {
            let discountAmount = total.value;
            if(discountAmount === 0){
                return "";
            }
            let classNameAmount = (discountAmount === 0) ? "add-discount" : "amount";
            let displayValue = (discountAmount === 0) ? "" : `${CurrencyHelper.format(discountAmount)}`;
            let className = ["totals-discount", "totals-action"];

            // if has any gate way payment is error or processing payment => user cannot use discount function
            if (hasPaidOrWaitingGatewayPayment) {
                classNameAmount = '';
                className = ["totals-discount"];
            }
            let title = total.title;
            let discount_type = quote.os_pos_custom_discount_type;
            let discount_amount = quote.os_pos_custom_discount_amount;
            if (discount_type && displayValue.length > 0) {
                if (discount_type === CustomDiscountService.DISCOUNT_TYPE_PERCENT) {
                    title = i18n.translator.translate(
                        'Custom discount ({{percent}}%)',
                        {percent: CurrencyHelper.formatNumberStringToCurrencyString(discount_amount)}
                    );
                } else {
                    title = i18n.translator.translate('Custom discount');
                }
            }

            return (
                <li className={className.join(" ")}>
                    <span className="mark">{title}</span>
                    {
                        quote.checking_promotion ? (
                            <img className="checking-promotion" src={LoadingImage} alt=""/>
                        ) : (
                            <span className={classNameAmount}>{displayValue}</span>
                        )
                    }
                </li>
            );
        }

        getRewardPointsDiscount(quote) {
            if (!RewardPointHelper.isEnabledRewardPoint()) {
                return;
            }
            let RewardPointService = require("../../../extension/reward-points/service/RewardPointService").default;
            const {t} = this.props;
            let pointDiscount = quote.rewardpoints_discount;

            if (RewardPointService.customerCanSpendPoint(quote.customer)) {
                const pointName = RewardPointHelper.getPointName();
                const usedPoint = quote.rewardpoints_spent;
                let title = t('{{pointName}} Discount', {pointName});

                if (usedPoint) {
                    title = t('{{pointName}} Discount ({{usedPoint}} {{pointName}})', {
                        pointName: usedPoint > 1
                            ? RewardPointHelper.getPluralOfPointName()
                            : RewardPointHelper.getPointName(),
                        usedPoint: NumberHelper.formatDisplayGroupAndDecimalSeparator(usedPoint)
                    });
                }

                this.addToTotals(
                    "spend_point",
                    title,
                    pointDiscount || 0,
                    ""
                );
            }
            if (
                quote.customer && (
                    RewardPointHelper.canEarnWhenSpend()
                    || (!quote.rewardpoints_spent && !RewardPointHelper.canEarnWhenSpend())
                )
            ) {
                this.addToTotals("earn_point", t('Customer will earn'),
                    quote.rewardpoints_earn || 0, ""
                );
            }
        }

        template() {
            HideMenuButton();
            const {quote, imageSize} = this.state;
            const {second_display_image, second_display_enable} = this.props;

            if (second_display_enable === undefined) {
                return <Loading/>
            }
            return !second_display_enable ?
                <span>{this.props.t('Please enable second screen in config')}</span>
                : (
                    <div className="container-fluid">
                        <div className="row second-display" id={'second-display'}>
                            <div className="col-xs-6 left-panel">
                                <div className={'banner'}>
                                    {!second_display_image && <span>{imageSize}</span>}
                                    {second_display_image && <img src={second_display_image} alt={"banner"}/>}
                                </div>
                            </div>
                            {
                                !!quote && !!quote.items && quote.items.length > 0 &&
                                <div className="col-xs-6 right-panel">
                                    {this.getCartHeader(quote)}
                                    {this.getCustomerButton(quote)}
                                    {this.getCartItems(quote)}
                                    {this.getCartTotals(quote)}
                                </div>
                            }
                        </div>
                    </div>
                )
        }
    }

    class SecondDisplayContainer extends CoreContainer {
        static className = 'SecondDisplayContainer';

        /**
         * get config of second display
         * @param state
         * @return {{ second_display_image, second_display_enable }}
         */
        static mapState(state) {
            const {config} = state.core;
            let second_display_image, second_display_enable;
            if (!!config && !!config.configs && !!config.configs.extension_attributes) {
                second_display_image = config.configs.extension_attributes.second_display_image;
                second_display_enable = config.configs.extension_attributes.second_display_enable;
            }
            return {second_display_image, second_display_enable};
        }
    }

    /**
     * @type {SecondDisplayContainer}
     */
    return ContainerFactory.get(SecondDisplayContainer).withRouter(
        ComponentFactory.get(SecondDisplayComponent),
    );
}



