import {listen} from "../../../../../../../event-bus";
import AmastyRewardsHelper from "../../../../../helper/AmastyRewardsHelper";
import CreateCreditmemoConstant from "../../../../../view/constant/order/creditmemo/CreateCreditmemoConstant";

export default class OrderCreateCreditmemoObserver {
    /**
     * constructor
     */
    constructor() {
        listen('refund_creditmemo_get_creditmemo_data_middle', (eventData) => {
            if (AmastyRewardsHelper.isEnabledAmastyRewards()) {
                let {key} = eventData;

                let extension_attributes = [
                    CreateCreditmemoConstant.REWARD_POINTS_TO_REFUND,
                    CreateCreditmemoConstant.EARNED_POINTS,
                ];
                // check key data
                eventData.isExtensionAttributes = extension_attributes.includes(key);
            }
        }, 'amasty_rewards');
        listen('component_order_create_creditmemo_reset_adjustments_after', (eventData) => {
            if (AmastyRewardsHelper.isEnabledAmastyRewards()) {
                let AmastyRewardsService = require("../../../../../service/AmastyRewardsService").default;
                AmastyRewardsService.setNeedResetCreditmemoAdjustmentsPoints(true);
            }
        }, 'amasty_rewards');
    }
}



