import {listen} from "../../../../../event-bus";
import AmastyRewardsHelper from "../../../helper/AmastyRewardsHelper";

export default class QuoteServiceObserver {
    constructor() {
        let removePoint = () => {
            if (AmastyRewardsHelper.isEnabledAmastyRewards()) {
                let AmastyRewardsService = require("../../../service/AmastyRewardsService").default;
                AmastyRewardsService.getUsedPoint() && AmastyRewardsService.removeUsedPoint();
            }
        };
        listen('service_quote_add_product_after', removePoint, 'amasty_rewards');
        listen('service_quote_update_qty_cart_item_after', removePoint, 'amasty_rewards');
        listen('service_quote_update_custom_price_cart_item_after', removePoint, 'amasty_rewards');
        listen('service_quote_remove_cart_item_after', removePoint, 'amasty_rewards');
    }
}



