import AmastyRewardsHelper from "../helper/AmastyRewardsHelper";
import NumberHelper from "../../../helper/NumberHelper";

export default {
    customer_button_after: [
        function (component) {
            const {customer} = component.props.quote;
            let isEnabledAmastyRewards = AmastyRewardsHelper.isEnabledAmastyRewards();
            let pointLabel = AmastyRewardsHelper.getBalanceLabel();

            if (isEnabledAmastyRewards
                && customer
                && customer.id
                && customer.extension_attributes
                && customer.extension_attributes.amasty_reward_balance
            ) {
                return component.props.t('({{point}} {{pointLabel}})', {
                    point: NumberHelper.formatDisplayGroupAndDecimalSeparator(
                        customer.extension_attributes.amasty_reward_balance
                    ),
                    pointLabel: pointLabel
                });
            }
            return '';
        }
    ]
}



