import LocalStorageHelper from '../../../helper/LocalStorageHelper';
import CoreComponent from "../../../framework/component/CoreComponent";
import CoreContainer from "../../../framework/container/CoreContainer";
import ContainerFactory from "../../../framework/factory/ContainerFactory";
import ComponentFactory from "../../../framework/factory/ComponentFactory";

export default function () {
    class QuoteLocalStorageComponent extends CoreComponent {
        static className = 'QuoteLocalStorageComponent';

        // eslint-disable-next-line no-unused-vars
        componentWillReceiveProps(nextProps, nextContext) {
            if (this.props.quote !== nextProps.quote) {
                LocalStorageHelper.set('quote', JSON.stringify(nextProps.quote));
            }
        }
    }

    class QuoteLocalStorageContainer extends CoreContainer {
        static className = 'QuoteLocalStorageContainer';

        /**
         * get config of second display
         * @param state
         * @return {{ second_display_image, second_display_enable }}
         */
        static mapState(state) {
            const {checkout} = state.core;
            let quote;
            if (!!checkout && !!checkout.quote) {
                quote = checkout.quote;
            }
            return {quote};
        }
    }

    /**
     * @type {QuoteLocalStorageContainer}
     */
    return ContainerFactory.get(QuoteLocalStorageContainer).withRouter(
        ComponentFactory.get(QuoteLocalStorageComponent),
    )
}




