import React from "react";
import AmastyRewardsHelper from "../../../../../helper/AmastyRewardsHelper";
import AmastyRewardsConstant from "../../../../../view/constant/AmastyRewardsConstant";

export default {
    template: {
        amasty_rewards: {
            sortOrder: 100,
            disabled: false,
            before: function() {
                let AmastySpendRewardPoint = require("../../../../../view/component/checkout/AmastySpendRewardPoint").default;
                if (AmastyRewardsHelper.isEnabledAmastyRewards()
                    && !this.showOnPages.includes(AmastySpendRewardPoint.className)
                ) {
                    this.showOnPages.push(AmastySpendRewardPoint.className);
                }
            },
        }
    },
    getTemplateTotal: {
        amasty_rewards: {
            sortOrder: 100,
            disabled: false,
            after: function(result, item) {
                if (!AmastyRewardsHelper.isEnabledAmastyRewards()) {
                    return result;
                }
                let AmastyEarnPoint = require("../../../../../view/component/checkout/cart/totals/AmastyEarnPoint").default;
                if (item.code === AmastyRewardsConstant.POINTS_EARN) {
                    return <AmastyEarnPoint key={item.code}
                                      quote={this.props.quote}
                                      total={item}
                                      showBackDrop={() => this.showBackDrop()}
                    />
                }
                let AmastyPointDiscount = require("../../../../../view/component/checkout/cart/totals/AmastyPointDiscount").default;
                if (item.code === AmastyRewardsConstant.POINTS_SPENT) {
                    return <AmastyPointDiscount key={item.code}
                                            quote={this.props.quote}
                                            total={item}
                                            showBackDrop={() => this.showBackDrop()}
                    />
                }
                return result;
            },
        }
    },
};



