import AmastyRewardsHelper from "../../helper/AmastyRewardsHelper";
import React from "react";
import NumberHelper from "../../../../helper/NumberHelper";

export default {
    grand_total_after: [
        function displayAmastyRewardSpentPoint(component) {
            let {order, t} = component.props;

            if (AmastyRewardsHelper.isEnabledAmastyRewards()
                && order.extension_attributes
                && order.extension_attributes.am_spent_reward_points
            ) {
                let pointLabel = AmastyRewardsHelper.getBalanceLabel();
                let displayValue = NumberHelper.formatDisplayGroupAndDecimalSeparator(
                    order.extension_attributes.am_spent_reward_points
                );
                return (
                    <li key='spent-point'>
                        <span className="title">{t('Spent')}</span>
                        <span className="value">{
                            t('{{point}} {{pointLabel}}', {
                                point: displayValue,
                                pointLabel: pointLabel
                            })
                        }</span>
                    </li>
                );
            }
            return null;
        },
        function displayAmastyRewardEarnedPoint(component) {
            let {order, t} = component.props;

            if (AmastyRewardsHelper.isEnabledAmastyRewards()
                && AmastyRewardsHelper.isShowDetailedInfoInOrderDetail()
                && order.extension_attributes
                && order.extension_attributes.am_earn_reward_points
            ) {
                let pointLabel = AmastyRewardsHelper.getBalanceLabel();
                let displayValue = NumberHelper.formatDisplayGroupAndDecimalSeparator(
                    order.extension_attributes.am_earn_reward_points
                );
                return (
                    <li key='earned-point'>
                        <span className="title">{t('Earned')}</span>
                        <span className="value">{
                            t('{{point}} {{pointLabel}}', {
                                point: displayValue,
                                pointLabel: pointLabel
                            })
                        }</span>
                    </li>
                );
            }
            return null;
        },
        function displayAmastyRewardRefundedPoint(component) {
            let {order, t} = component.props;

            if (AmastyRewardsHelper.isEnabledAmastyRewards()
                && AmastyRewardsHelper.isShowDetailedInfoInOrderDetail()
                && order.extension_attributes
                && order.extension_attributes.am_refund_reward_points
            ) {
                let pointLabel = AmastyRewardsHelper.getBalanceLabel();
                let displayValue = NumberHelper.formatDisplayGroupAndDecimalSeparator(
                    order.extension_attributes.am_refund_reward_points
                );
                return (
                    <li key='refunded-point'>
                        <span className="title">{t('Refunded')}</span>
                        <span className="value">{
                            t('{{point}} {{pointLabel}}', {
                                point: displayValue,
                                pointLabel: pointLabel
                            })
                        }</span>
                    </li>
                );
            }
            return null;
        },
        function displayAmastyRewardDeductedPoint(component) {
            let {order, t} = component.props;

            if (AmastyRewardsHelper.isEnabledAmastyRewards()
                && AmastyRewardsHelper.isShowDetailedInfoInOrderDetail()
                && order.extension_attributes
                && order.extension_attributes.am_deduct_reward_points
            ) {
                let pointLabel = AmastyRewardsHelper.getBalanceLabel();
                let displayValue = NumberHelper.formatDisplayGroupAndDecimalSeparator(
                    order.extension_attributes.am_deduct_reward_points
                );
                return (
                    <li key='deducted-point'>
                        <span className="title">{t('Subtracted')}</span>
                        <span className="value">{
                            t('{{point}} {{pointLabel}}', {
                                point: displayValue,
                                pointLabel: pointLabel
                            })
                        }</span>
                    </li>
                );
            }
            return null;
        },
    ]
}



