import {listen} from "../../../../../../event-bus";
import AmastyRewardsHelper from "../../../../helper/AmastyRewardsHelper";

export default class TotalServiceObserver {
    constructor() {
        listen(
            'service_quote_init_total_collectors',
            (eventData) => {
                if (AmastyRewardsHelper.isEnabledAmastyRewards()) {
                    let AmastyPointTotalService = require("../../../../service/quote/total/AmastyPointTotalService").default;
                    eventData.service.totalCollectors.push({
                        name: "amasty_rewards",
                        class: AmastyPointTotalService,
                        sort_order: 410,
                    });
                }
            },
            'amasty_rewards'
        );
    }
}



