import deepmerge from "../framework/Merge";
// IMPORT_LINES
import __0_add_vat_numberConfig from './add-vat-number/etc/config.js';
import __1_amasty_rewardsConfig from './amasty-rewards/etc/config.js';
import __2_payment_offlineConfig from './payment-offline/etc/config.js';
import __3_reward_pointsConfig from './reward-points/etc/config.js';
import __4_stripe_terminal_paymentConfig from './stripe-terminal-payment/etc/config.js';
import __5_take_shipmentConfig from './take-shipment/etc/config.js';
// IMPORT_LINES

/**
 * Collect all config.js each extension module
 *
 * @return {*}
 */
function getConfig() {
    return deepmerge.all([
        {},
        {},
        // MODULE_LINES
        __0_add_vat_numberConfig,
        __1_amasty_rewardsConfig,
        __2_payment_offlineConfig,
        __3_reward_pointsConfig,
        __4_stripe_terminal_paymentConfig,
        __5_take_shipmentConfig,
        // MODULE_LINES
    ])
}

let cachedConfig = getConfig();

/**
 *
 * cache config
 *
 * @return {*}
 */
export default () => {
    if (!cachedConfig) {
        cachedConfig = getConfig()
    }

    return cachedConfig
}

export function updateConfig(newConfig) {
    cachedConfig = newConfig;
}



