import {Observable} from 'rxjs';
import EpicFactory from "../../../../../framework/factory/EpicFactory";
import AmastyRewardsConstant from "../../constant/AmastyRewardsConstant";
import AmastyRewardsAction from "../../action/AmastyRewardsAction";
import AmastyRewardsService from "../../../service/AmastyRewardsService";
import QuoteService from "../../../../../service/checkout/QuoteService";
import QuoteAction from "../../../../../view/action/checkout/QuoteAction";
import AppStore from "../../../../../view/store/store";

function AmastyCheckEarningPointEpic(action$, store) {
    return action$.ofType(AmastyRewardsConstant.CHECK_EARNING_POINT)
        .mergeMap(async action => {
            let quote = action.quote;
            if (!quote.customer) {
                return AmastyRewardsAction.checkEarningPointResult();
            }
            let quoteId = quote.id;
            let customerId = quote.customer_id;
            let validEarningRules = [];
            let createdQuoteId;
            try {
                let result = await AmastyRewardsService.checkEarningPoint(quote);
                result.valid_rules.forEach(rule => validEarningRules.push(JSON.parse(rule)));
                createdQuoteId = result.quote_id;
            } catch (e){
                validEarningRules = [];
            }

            let currentQuote = store.getState().core.checkout.quote;

            if (currentQuote.id === quoteId
                && currentQuote.customer_id === customerId
            ) {
                currentQuote.amasty_rewards_valid_earning_rules = validEarningRules;
                currentQuote.amasty_rewards_quote_id = createdQuoteId;
                QuoteService.collectTotals(currentQuote);
                AppStore.dispatch(QuoteAction.setQuote(currentQuote));
            }

            return AmastyRewardsAction.checkEarningPointResult();
        }).catch(() => Observable.of(AmastyRewardsAction.checkEarningPointResult()));
}

AmastyCheckEarningPointEpic.className = "AmastyCheckEarningPointEpic";

export default EpicFactory.get(AmastyCheckEarningPointEpic);



