import AbstractResourceModel from "../AbstractResourceModel";

export default class PerformanceResourceModel extends AbstractResourceModel {
    static className = 'PerformanceResourceModel';

    /**
     * Constructor
     * @param props
     */
    constructor(props) {
        super(props);
        this.state = {resourceName : 'Performance'};
    }

    /**
     * Call get all payment items
     *
     * @returns {Object|*|FormDataEntryValue[]|string[]}
     */
    getAll() {
        return this.getResourceOffline().getAll();
    }

    /**
     * Delete all table
     *
     * @returns {Object|*|FormDataEntryValue[]|string[]}
     */
    deleteAll() {
        return this.getResourceOffline().deleteAll();
    }

    /**
     * Sync log
     * @param params
     * @return {*|promise}
     */
    async saveLog(params) {
        return await this.getResourceOnline().saveLog(params);
    }
}


